window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":176,"source":"خطبه 176.docx","mode":"explicit-parts","parts":["خطبه ۱۷۶\nبخش اول\nمتن:\nو من خطبة له (علیه السلام) و فيها يَعِظ و يبيّن فضل القرآن و يَنهى عن البدعة:\nعِظَة الناس:\nانْتَفِعُوا بِبَيَانِ اللَّهِ وَ اتَّعِظُوا بِمَوَاعِظِ اللَّهِ وَ اقْبَلُوا نَصِيحَةَ اللَّهِ، فَإِنَّ اللَّهَ قَدْ أَعْذَرَ إِلَيْكُمْ بِالْجَلِيَّةِ وَ [أَخَذَ] اتَّخَذَ عَلَيْكُمُ الْحُجَّةَ، وَ بَيَّنَ لَكُمْ مَحَابَّهُ مِنَ الْأَعْمَالِ وَ مَكَارِهَهُ مِنْهَا، لِتَتَّبِعُوا هَذِهِ وَ تَجْتَنِبُوا هَذِهِ؛ فَإِنَّ رَسُولَ اللَّهِ (صلی الله علیه وآله) كَانَ يَقُولُ إِنَّ الْجَنَّةَ حُفَّتْ بِالْمَكَارِهِ وَ إِنَّ النَّارَ حُفَّتْ بِالشَّهَوَاتِ. وَ اعْلَمُوا أَنَّهُ مَا مِنْ طَاعَةِ اللَّهِ شَيْءٌ إِلَّا يَأْتِي فِي كُرْهٍ، وَ مَا مِنْ مَعْصِيَةِ اللَّهِ شَيْءٌ إِلَّا يَأْتِي فِي شَهْوَةٍ، فَرَحِمَ اللَّهُ امْرَأً نَزَعَ عَنْ شَهْوَتِهِ وَ قَمَعَ هَوَى نَفْسِهِ، فَإِنَّ هَذِهِ النَّفْسَ أَبْعَدُ شَيْءٍ مَنْزِعاً، وَ إِنَّهَا لَا تَزَالُ تَنْزِعُ إِلَى مَعْصِيَةٍ فِي هَوًى.\nترجمه:\nاز آن چه خداوند بيان فرموده، بهره گيريد و از مواعظ و اندرزهاى او پند پذيريد و نصايح او را (با جان و دل) قبول کنيد ; چه اين که خداوند با دليل هاى روشن، راه عذر را به روى شما بسته و حجّت را تمام کرده است. اعمالى را که دوست دارد و آن چه را ناخوش دارد براى شما تبيين نموده است تا از آن ها تبعيّت کنيد و از اين ها دورى گزينيد ; زيرا رسول خدا(صلى الله عليه وآله) مى فرمود: بهشت در ميان ناراحتى ها و دوزخ در ميان شهوات پيچيده شده است و بدانيد هيچ طاعتى نيست جز اين که انسان آن را با ناراحتى انجام مى دهد و هيچ معصيتى نيست جز اين که با شهوت (و علاقه) مرتکب آن مى شود.\nرحمت خدا بر کسى که خود را از شهوات جدا سازد و هواى نفس را مهار کند ; چرا که جلوگيرى از نفس سرکش از مشکل ترين کارهاست و اين نفس، همواره به گناه و هواپرستى ميل دارد.\nتفسیر:\nخطبه در ابتدای حکومت امیرالمؤمنین صلوات‌الله‌علیه صادر شده است. محتوای کلی خطبه، موعظه، شرح و کیفیت قرآن و بدعت است. حضرت در این خطبه سه توصیه تقوایی می‌فرماید:\n♦ اِنتَفِعُوا بِبَیانِ اللهِ\n۱. از آنچه خداوند برای شما به‌روشنی بیان کرده است، بهره ببرید.\nبیان‌شده‌ها، از جمله واجبات و محرّمات، هستند. آن‌ها را رعایت کنید و نسبت به آن‌ها اهتمام بورزید. این مطالب صرفاً برای شنیدن و لذت‌بردن نیست؛ بلکه باید از آنچه بیان شده است، بهره برد.\n♦ وَاتَّعِظُوا بِمَوَاعِظِ اللهِ\n۲. مواعظ الهی را با گوش جان بشنوید و به آن‌ها عمل کنید. مواعظ، در قالب مستحبّات، مکروهات و آداب بیان شده‌اند. آن‌ها را بپذیرید و در برابرشان پذیرنده باشید.\nحالت درونی شما باید دگرگون و اثرپذیر باشد.\n♦ وَاقْبَلُوا نَصِیحَةَ اللهِ\n۳. آنچه را خداوند به‌عنوان نصیحت برای شما بیان کرده است، با گوش جان بشنوید.\nنصیحت‌های خداوند در قالب آثار اعمال بیان شده‌اند؛ مانند صدقه‌ای که ده برابر یا هفتاد برابر پاداش دارد، اما ممکن است این مسئله با حساب‌وکتاب ذهنی ما سازگار نباشد.\nبهره‌مندی، موعظه پذیری و پذیرفتن نصیحت، کاری ارادی است. صرف وجود یک استاد متبحّر کافی نیست؛ باید در کنار آن، عمل نیز باشد تا رشد صورت بگیرد. انسان با عمل، تا چه اندازه می‌تواند شاکله وجودی خود را شبیه اهل‌بیت کند!\nبا صاحبان مواعظ تا چه اندازه می‌توان سنخیت پیدا کرد! ملاک، هم‌سنخ شدن است؛ زیرا بسیاری از مردم پیامبر را دیدند، اما عبرت نگرفتند و با او هم‌سنخ نشدند.\nحضرت در کلامی در غررالحکم فرموده است:\n《فِی کلِّ تَجْرِبَةٍ مَوْعِظَةٌ》\nهر تجربه شخصی، خود موعظه‌ای است.\nمؤمن از یک سوراخ دو بار گزیده نمی‌شود؛ یعنی باید موعظه پذیر باشد. هر تجربه شخصی، موعظه‌ای مهم است. انسان در خطای پیشین، سلب توفیق را تجربه کرده است، اما از آن تجربه موعظه نمی‌گیرد.\n✳️ نکته: در ادبیات عرب، هنگامی که یک‌بار اسم ظاهر می‌آید، برای تکرار، ضمیر آورده می‌شود.\nذکر لفظ «الله» سه بار پشت‌سرهم در جمله، نکته‌ای دارد. همین قاعده دقیقاً در قرآن نیز دیده می‌شود:\n《فَإِنْ تَابُوا وَأَصْلَحُوا وَاعْتَصَمُوا بِاللَّهِ وَأَخْلَصُوا دِینَهُمْ لِلَّهِ فَسَوْفَ یؤْتِی اللَّهُ الْمُؤْمِنِینَ أَجْرًا عَظِیمًا، نِسَاءٌ - ۱۴۶》\nیکی از دلایل تکرار نام خدا، عظمت بخشیدن به اوست؛ یعنی برای بزرگداشت خداوند، نام او پی‌درپی ذکر می‌شود.\nدلیل دوم، اوج محبت است. در چنین مواقعی، ادبیات معمولاً نام را به ضمیر تبدیل می‌کند، ولی حضرت از روی محبت، نام خدا را به طور مکرر تکرار می‌کند و در این کلام نیز همین قاعده را رعایت می‌فرماید.\n♦ فَإِنَّ اللهَ قَدْ أَعْذَرَ إِلَیکمْ بِالْجَلِیةِ\nخداوند نه‌تنها اصل احکام را بیان کرده، بلکه اعمالی را نیز که دوست دارد، آشکار ساخته است تا راه عذر را ببندد؛ زیرا دلایل واضح و روشن اقامه کرده است. از درون، پیامبری به نام عقل و وجدان، و از بیرون، پیامبران، اوصیا و علما را قرار داده است و برای هیچ‌کس جای عذرتراشی باقی نگذاشته است. «عقاب بلا بیان» قبیح است و خدای حکیم کار قبیح انجام نمی‌دهد. خداوند پیش از بیان آشکار، کسی را مؤاخذه نمی‌کند.\n♦ وَأَخَذَ عَلَیکمُ الْحُجَّةَ\nخداوند حجت را بر شما تمام کرده و آنچه را برای هدایت و سعادت انسان لازم بوده است، نشان داده است.\n♦ وَبَینَ لَکمْ مَحَابَّهُ مِنَ الْأَعْمَالِ وَمَکارِهَهُ مِنْهَا\nخداوند به‌صراحت و آشکارا آنچه را دوست دارد، بیان کرده است؛ یعنی محبوب‌های خود را، از جمله مستحبّات، روشن ساخته است.\nاحسان به پدر و مادر و دستگیری از دیگران را به طور مستقل و باارزش فراوان بیان کرده است و آنچه را محبوب خداوند نیست و خشنودی او را در پی ندارد، نیز به‌روشنی ذکر کرده است. در قرآن صریحاً آمده است:\n《إِنَّ اللهَ لَا یحِبُّ الْمُعْتَدِینَ، یحِبُّ الْمُقْسِطِینَ، لَا یحِبُّ الظَّالِمِینَ، یحِبُّ الصَّابِرِینَ، لَا یحِبُّ الْفَرِحِینَ، یحِبُّ التَّوَّابِینَ》\n♦ لِتَتَّبِعُوا هَذِهِ وَتَجْتَنِبُوا هَذِهِ\nهمه چیز به‌روشنی بیان شده است تا شما از محبوب‌ها پیروی کنید و از ناپسندها دوری‌گزینید.\n♦ فَإِنَّ رَسُولَ اللهِ صَلَّی اللهُ عَلَیهِ وَآلِهِ کانَ یقُولُ: إِنَّ الْجَنَّةَ حُفَّتْ بِالْمَکارِهِ، وَإِنَّ النَّارَ حُفَّتْ بِالشَّهَوَاتِ\nحضرت به سخن پیامبر استشهاد سختی‌ها پیامبر بارها می‌فرمود: به‌درستی که بهشت با سختی‌ها، رنج‌ها، دندان فشردن و چشم فروبستن احاطه شده است و جهنم با شهوت‌ها، تمایلات و راحتی‌ها احاطه شده است.\nهنگامی که حضرت سخنی از پیامبر نقل می‌کند، این نشان‌دهنده اوج اعتماد به آن سخن است. شاید کسی از نظر سیاسی امیرالمؤمنین را قبول نداشته باشد، اما همه مسلمان‌اند و باید به کلام پیامبر اعتماد کنند.\nبهشت مسیری پرپیچ‌وخم است؛ بنابراین برای رسیدن به آن باید سختی اعمال و دشواری‌های آن را تحمل کرد. تمام تمایلات نفسانی، راحتی و آسایش بی‌دردسر، سرانجامی جز جهنم ندارد.\nگناهکار آنچه را زیبا می‌بیند، زیبا جلوه می‌دهد و جذب آن می‌شود؛ اما این، حقیقت دنیا نیست، بلکه همان «زَینَ لَهُمُ الشَّیطَانُ» است. وگرنه باطن دنیا سراسر سختی است.\nانجام گناه نیز دشواری دارد، اما شیطان آن را آرایش می‌دهد و آسان نشان می‌دهد. چنین نیست که عبادت سخت و گناه آسان باشد. اعمال جهنمی، چون مطابق امیال نفسانی هستند، شاید آسان‌تر به نظر برسند؛ زیرا نفس به انحراف تمایل دارد و به چیزی که محدودیت نداشته باشد، مشتاق است. واردشدن در این تمایلات، سرانجام انسان را در دام شیطان و جهنم گرفتار می‌کند.\n✳️ امام باقر صلوات‌الله‌علیه فرمودند:\nگویا همین جمله را معنا می‌کند:\n《الْجَنَّةُ مَحْفُوفَةٌ بِالْمَکارِهِ وَالصَّبْرِ》\nسختی‌هایی که با صبر همراه باشند. صبر بر طاعت، یکی از انواع مهم صبر است.\nصبر بر طاعت و صبر بر معصیت، به‌طریق‌اولی، از صبر بر مصیبت دشوارتر است؛ زیرا انگیزه و سوز مصیبت، به‌تدریج فروکش می‌کند. در حکمت‌ها نیز فرموده‌اند: انسان جوانِ عفیف نزدیک است که به فرشته تبدیل شود.\n《کانَ الْعَفِیفُ أَنْ یکونَ مَلَکا》\n♦ وَاعْلَمُوا أَنَّهُ مَا مِنْ طَاعَةِ اللهِ شَیءٌ إِلَّا یأْتِی فِی کرْهٍ\nبدانید هیچ طاعتی از طاعات الهی نیست، مگر اینکه با نوعی ناخشنودی و دشواری همراه است.\n♦ وَمَا مِنْ مَعْصِیةِ اللهِ شَیءٌ إِلَّا یأْتِی فِی شَهْوَةٍ\nو هیچ معصیتی نیست، مگر اینکه در آن لذت و چیزی موافق میل انسان وجود دارد.\nاین جمله حضرت درباره بیشتر انسان‌هاست؛ زیرا اکثر مردم به عبادت اشتیاق ندارند و آن را با سختی انجام می‌دهند. البته گروهی از انسان‌ها فضای متفاوتی دارند.\nدرون‌مایه بیشتر انسان‌ها این‌گونه است که نفس از عبادت ناراحت می‌شود و با آن همراهی نمی‌کند. پرداخت خمس و زکات و انفاق دشوار است و نفس آن را نمی‌پذیرد. در عبادت عقب می‌کشد و اخم می‌کند، اما در معاصی با سرعت و لذت می‌شتابد.\nاکثریت مؤمنان و مسلمانان چنین هستند؛ اما کفار که اساساً به عبادت کاری ندارند. بیشتر مؤمنان، به طمع بهشت یا از ترس جهنم، از عملی پرهیز می‌کنند یا آن را انجام می‌دهند.\nبااین‌حال، گروهی از انسان‌ها از روی اکراه، اجبار و بی‌میلی عبادت نمی‌کنند؛ بلکه با عشق و لذت به عبادت می‌پردازند.\n《وَاسْتَعِینُوا بِالصَّبْرِ وَالصَّلَاةِ وَإِنَّهَا لَکبِیرَةٌ إِلَّا عَلَی الْخَاشِعِینَ، بَقَرَةٌ - ۴۵》\nطاعت برای همه سخت است، مگر برای کسانی که دلی خاشع دارند. عبادت برای آنان نه‌تنها ناخوشایند نیست، بلکه با میل و اشتیاق انجام می‌شود.\n✳️ مرحوم کلینی در جلد دوم کافی روایتی نقل کرده است:\n《أَفْضَلُ النَّاسِ مَنْ عَشِقَ الْعِبَادَةَ وَمَعَانَقَهَا وَأَحَبَّهَا بِقَلْبِهِ وَعَاشَ بِجَسَا》\nبرترین مردم کسی است که عاشقَ لَهَا》\nبرترین مردم کسی است که عاشق عبادت باشد، آن را در آغوش بگیرد، با قلب خوددوستش بدارد، جسم خود را با آن درگیر کند و برای آن فراغت فراهم آورد.\nتمام اعضای خود را مشغول عبادت می‌کند و برای عبادت، فرصت و فراغت فراهم می‌سازد.\nدر دعای افتتاح، مرتبه‌ای بالاتر از این بیان شده است. انسان باخدا عشق‌بازی می‌کند، ناز خدا را می‌خرد و خود نیز ناز می‌کند. همیشه مسئله، نیاز و طلب‌کردن نیست:\n《مُدِلًّا عَلَیک فِیمَا قَصَدْتُ فِیهِ إِلَیک》\nبه تعبیر آیت‌الله جوادی، «حفظه‌الله»، این عبارت برای نیاز نیامده، بلکه برای ناز آمده است؛ یعنی «مُدِلًّا».\nجمله امیرالمؤمنین که در عبادت کراهت وجود دارد، درباره بیشتر مردم صادق است؛ ولی انسان می‌تواند به جایی برسد که ملکه عبادت در وجودش علم شود و ترک معاصی در وجودش قد علم کند.\nبرای اینکه تکلیف خود را بدانیم، باید ببینیم با عبادت جزو کدام دسته هستیم: آیا عبادت ما از روی کراهت و سختی است یا آن را با عشق انجام می‌دهیم؟\nمیان عبادت و عادت تفاوت بسیار است.\nشهید مطهری جمله‌ای راهگشا دارند:\nببینید عبادت شما از روی عادت است یا نه!\nآیا در بعضی عبادت‌ها پرشور هستید و سنگ آن را به سینه می‌زنید یا در همه موارد عبادی چنین حالتی دارید؟\nدر تأخیرنینداختن نماز مصرّ هستید، ولی در تأخیرنینداختن امر به در یک سطح هستند. در واجبات تفاوتید!\nاعمال و عبادات، همگی در یک سطح هستند. در واجبات تفاوتی وجود ندارد و نسبت به همه آن‌ها باید حساس بود. این معیار خوبی است.\nهمه عبادات واجب‌اند؛ نماز، امربه‌معروف، دستگیری از مظلوم و برپایی مجلس امام حسین علیه‌السلام. ممکن است نسبت به مجلس اباعبدالله حساس باشیم، ولی نسبت به کشته‌شدن مردم یمن دردی احساس نکنیم.\nبه دو یا سه عمل حساس هستیم و بقیه اعمال بدون دغدغه سپری می‌شوند. با این روش، عبادتی در کار نیست؛ بلکه عمل از روی عادت است. اما اگر نسبت به همه اعمال حساس و مصرّ باشید، عبادت شما از روی محبت خواهد بود.\nعبادت، منهای «ب»، عادت است.\nاگر ابتدا و انتهای آن حذف شود، «باد» باقی می‌ماند؛ بادِ غرور و نخوت.\nممکن است عبادت به تلمبه‌ای تبدیل شود که انسان را از باد پر می‌کند. این باد قرار است تا کجا ادامه پیدا کند و چه زمانی بترکد؟\nنباید با عبادت، دچار غرور شوید؛ بلکه باید مانند درخت باشید: هرچه پربارتر و سنگین‌تر، سربه‌زیرتر.\n♦ فَرَحِمَ اللهُ رَجُلًا نَزَعَ عَنْ شَهْوَتِهِ، وَقَمَعَ هَوَی نَفْسِهِ\nخداوند رحمت کند کسی را که تمایلات نفسانی را از دل برکند و ریشه آن‌ها را قطع کند و هوای نفس خود را مغلوب و سرکوب سازد.\nرحمت رحمانیّه شامل همه می‌شود. از تابش خورشید و نزول باران، همگان بهره می‌برند؛ اما رحمت رحیمیّه همگانی نیست و گروه خاصی از مردم را در برمی‌گیرد.\nچرا همیشه هوای نفس غالب باشد؟ یک‌بار هم باید او شکست بخورد. اگر باقدرت در برابر هوای نفس بایستید، خداوند نیز با تمام قدرت پشت شما می‌ایستد. جلب رحمت رحیمیّه باعث می‌شود خداوند با رحمت ویژه خود، از گناهان دیگر جلوگیری کند.\n♦ فَإِنَّ هَذِهِ النَّفْسَ أَبْعَدُ شَیءٍ مَنْزَعًا\nاین نفس امّاره، کنده‌شدنش دشوارترین و دورترین کار است.\nاین دشمن نامرئیِ درون، به تمام گوش، چشم و زبان را در اختیار مهارکردن آن بسیار دشوار است. مدام گوش، چشم و زبان را در اختیار می‌گیرد و با کوچک‌ترین غفلت، انسان را به معصیت وارد می‌کند. دشمن نظامی و جهاد اصغر، با ضعیف است.\nسلاح نفس بسیار قدرتمند و کشنده است. بر، بسیار ضعیف است.\nسلاح نفس بسیار قدرتمند و کشنده است. نفس تمام قوای حیاتی و عقل و مرکز کنترل انسان را در اختیار می‌گیرد. اگر شیطان نیز با آن همراه شود، وامصیبتا! مبارزه با نفس بسیار دشوار است، اما شدنی است.\n♦ وَإِنَّهَا لَا تَزَالُ تَنْزِعُ إِلَی مَعْصِیةٍ فِی هَوًی\nنفس امّاره همیشه به هواپرستی و معصیت اشتیاق دارد و با چاشنی هوس، انسان را تحریک می‌کند و صدها نوع گناه را پیشروی او قرار می‌دهد.\nاگرچه نفس حریفی قدرتمند است، باید با آن مبارزه کرد. می‌توان آن را گرفتار کرد و شرّش را از سر خود بازداشت.\n✳️ در این جنگ نابرابر چه باید کرد؟\nراهکار رام کردن این دشمن قدرتمند چیست؟ چگونه می‌توان تسلّط نفس را کاهش داد؟\nدر مناجات شعبانیه آمده است:\n《إِلَهِی لَمْ تَکنْ لِی حَوْلٌ فَأَنْتَقِلَ بِهِ عَنْ مَعْصِیتِک إِلَّا فِی وَقْتٍ أَیقَظْتَنِی فِی مَحَبَّتِک وَکمَا أَرَدْتَ أَنْ أَکونَ کنْتُ》\nخدایا، برای ترک گناه هیچ توان و نیرویی ندارم، مگر اینکه بامحبت خود مرا بیدار کنی و مرا از خواب غفلت برهانی و آن‌گونه باشم که تو می‌خواهی.\nبا عشق می‌توان هر کاری را برای محبوب انجام داد. اگر عشق نباشد، کارها یا از روی ترس انجام می‌شوند یا برای رسیدن به نعمت. اگر نیرویی قوی‌تر و نقد در برابر نفس ظاهر شود، نفس به‌سرعت رام می‌شود؛ اما بامحبت و عشق، نفس به‌گونه‌ای رام می‌شود که دل محبوب را نرنجاند.\nاللَّهُمَّ لَا تَجْعَلْنَا نَظَرَنَا فِیهِ غَفْلَةً","بخش دوم\nمتن:\nوَ اعْلَمُوا عِبَادَ اللَّهِ، أَنَّ الْمُؤْمِنَ [لَا يُمْسِي وَ لَا يُصْبِحُ] لَا يُصْبِحُ وَ لَا يُمْسِي إِلَّا وَ نَفْسُهُ ظَنُونٌ عِنْدَهُ، فَلَا يَزَالُ زَارِياً عَلَيْهَا وَ مُسْتَزِيداً لَهَا؛ فَكُونُوا كَالسَّابِقِينَ قَبْلَكُمْ وَ الْمَاضِينَ أَمَامَكُمْ، قَوَّضُوا مِنَ الدُّنْيَا تَقْوِيضَ الرَّاحِلِ، وَ طَوَوْهَا طَيَّ الْمَنَازِلِ.\nفضلُ القرآن:\nوَ اعْلَمُوا أَنَّ هَذَا الْقُرْآنَ هُوَ النَّاصِحُ الَّذِي لَا يَغُشُّ وَ الْهَادِي الَّذِي لَا يُضِلُّ وَ الْمُحَدِّثُ الَّذِي لَا يَكْذِبُ، وَ مَا جَالَسَ هَذَا الْقُرْآنَ أَحَدٌ إِلَّا قَامَ عَنْهُ بِزِيَادَةٍ أَوْ نُقْصَانٍ، زِيَادَةٍ فِي هُدًى أَوْ نُقْصَانٍ مِنْ عَمًى؛ وَ اعْلَمُوا أَنَّهُ لَيْسَ عَلَى أَحَدٍ بَعْدَ الْقُرْآنِ مِنْ فَاقَةٍ وَ لَا لِأَحَدٍ قَبْلَ الْقُرْآنِ مِنْ غِنًى، فَاسْتَشْفُوهُ مِنْ أَدْوَائِكُمْ وَ اسْتَعِينُوا بِهِ عَلَى لَأْوَائِكُمْ، فَإِنَّ فِيهِ شِفَاءً مِنْ أَكْبَرِ الدَّاءِ وَ هُوَ الْكُفْرُ وَ النِّفَاقُ وَ الْغَيُّ وَ الضَّلَالُ. فَاسْأَلُوا اللَّهَ بِهِ وَ تَوَجَّهُوا إِلَيْهِ بِحُبِّهِ وَ لَا تَسْأَلُوا بِهِ خَلْقَهُ، إِنَّهُ مَا تَوَجَّهَ الْعِبَادُ إِلَى اللَّهِ تَعَالَى بِمِثْلِهِ. وَ اعْلَمُوا أَنَّهُ شَافِعٌ مُشَفَّعٌ وَ قَائِلٌ مُصَدَّقٌ، وَ أَنَّهُ مَنْ شَفَعَ لَهُ الْقُرْآنُ يَوْمَ الْقِيَامَةِ شُفِّعَ فِيهِ وَ مَنْ مَحَلَ بِهِ الْقُرْآنُ يَوْمَ الْقِيَامَةِ صُدِّقَ عَلَيْهِ، فَإِنَّهُ يُنَادِي مُنَادٍ يَوْمَ الْقِيَامَةِ: أَلَا إِنَّ كُلَّ حَارِثٍ مُبْتَلًى فِي حَرْثِهِ وَ عَاقِبَةِ عَمَلِهِ، غَيْرَ حَرَثَةِ الْقُرْآنِ، فَكُونُوا مِنْ حَرَثَتِهِ وَ أَتْبَاعِهِ؛ وَ اسْتَدِلُّوهُ عَلَى رَبِّكُمْ وَ اسْتَنْصِحُوهُ عَلَى أَنْفُسِكُمْ وَ اتَّهِمُوا عَلَيْهِ آرَاءَكُمْ وَ اسْتَغِشُّوا فِيهِ أَهْوَاءَكُمْ.\nترجمه:\nبدانيد اى بندگان خدا که انسان با ايمان، صبح و شام بر او نمى گذرد مگر اين که نزد خويش متهم است. پيوسته از خود عيب مى گيرد (و خويشتن را نقد مى کند) و براى خود طالب تکامل و فزونى است; بنابراين همچون پيشينيان و گذشتگان (صالح) خود باشيد که قبل از شما بودند. آن ها شبيه مسافرى بودند که عمودهاى خيمه را برگرفته و طى طريق مى کند (دنيا را گذرگاهى مى دانستند به سوى سراى جاودان).\nبدانيد اين قرآن، پند دهنده اى است که هرگز کسى را نمى فريبد و هدايتگرى است که هيچ گاه گمراه نمى سازد و سخنگويى است که هرگز دروغ نمى گويد. هيچ کس در کنار اين قرآن ننشسته جز اين که از کنار آن با زياده يا نقصانى برخاسته ; زيادتى در هدايت يا نقصانى از کوردلى و جهالت. و بدانيد هيچ کس با داشتن قرآن، فقر و بيچارگى ندارد و هيچ کس بدون آن غنا و بى نيازى نخواهد داشت. حال که چنين است براى درمان بيمارى هاى خود از قرآن شفا بطلبيد و براى پيروزى بر شدايد و مشکلات از آن يارى بجوييد ; زيرا در قرآن شفاى سخت ترين بيمارى ها يعنى کفر و نفاق و جهل و ضلالت است، بنابراين آن چه را مى خواهيد به وسيله قرآن از خدا بخواهيد و با محبّت قرآن به سوى خدا روى آوريد، و هرگز به وسيله آن از مخلوقات او چيزى نخواهيد ; زيرا بندگان به چيزى مانند آن به خدا تقرّب نجسته اند.\nبدانيد قرآن، شفاعت کننده اى است که شفاعتش مورد قبول و گوينده اى است که سخنش مقبول است. آن کس که قرآن در روز قيامت براى او شفاعت کند مشمول شفاعت مى شود و آن کس که قرآن در قيامت از وى شکايت کند گواهى اش بر ضد او پذيرفته خواهد شد ; چه اين که روز قيامت، منادى صدا مى زند: آگاه باشيد! امروز هر کس گرفتار بذرى است که افشانده و در گرو عاقبت اعمال خويش است ; جز آنان که بذر قرآن افشاندند. شما نيز از بذر افشانان قرآن و پيروان آن باشيد. پروردگارتان را با قرآن بشناسيد و خويشتن را با آن اندرز دهيد و در برابر قرآن، آراى خود را متهم کنيد و خواسته هاى نفسانى خويش را در برابر آن نادرست بشماريد.\nتفسیر:\nوَاعْلَمُوا أَنَّ هَذَا الْقُرْآنَ هُوَ النَّاصِحُ الَّذِی لَا یغُشُّ، وَالْهَادِی وَالْمُحَدِّثُ الَّذِی لَا یکذِبُ.\nبدانید این قرآن، نصیحت‌کننده‌ای است که هیچ‌گاه فریب نمی‌دهد و هدایت‌گری است که هرگز گمراه نمی‌کند؛ همچنین سخن‌گویی است که دروغ در محضر او راه ندارد.\nوَمَا جَالَسَ هَذَا الْقُرْآنَ أَحَدٌ إِلَّا قَامَ عَنْهُ بِزِیادَةٍ أَوْ نُقْصَانٍ، زِیادَةٍ فِی هُدًی أَوْ نُقْصَانٍ مِنْ عَمًی.\nهیچ‌کس با قرآن همنشین نمی‌شود، مگر آنکه از کنار آن با افزایشی یا کاهشی برمی‌خیزد؛ افزایشی در هدایت یا کاهشی از کوری و جهل.\nهمنشینی آدابی دارد. اگر همنشین کسی شدیم، باید شبیه او شویم. صرف خواندن، همنشینی به شمار نمی‌آید. فلاسفه می‌گویند سنخیت است که سبب همنشینی می‌شود.\nاعْلَمُوا أَنَّهُ لَیسَ عَلَی أَحَدٍ بَعْدَ الْقُرْآنِ مِنْ فَاقَةٍ، وَلَا لِأَحَدٍ قَبْلَ الْقُرْآنِ مِنْ غِنًی.\nهیچ‌کس پس از همنشینی با قرآن، فقیر نیست و هیچ‌کس پیش از انس با قرآن، غنا ندارد. برخی گفته‌اند مقصود از این غنا و فقر، معنای معنوی آن است؛ ولی ازآنجاکه دلیلی بر صرفاً معنوی بودن اثر قرآن وجود ندارد، رزق مادی نیز می‌تواند مقصود باشد.\nیکی از عوامل جذب رزق، انس با قرآن است. اگر کسی ثروت داشته باشد، ولی همنشین قرآن نباشد، غنی نیست. میان ثروتمندی و غنا تفاوت وجود دارد. این غنا و فقر به میزان انس انسان با قرآن وابسته است. ممکن است کسی فقیر باشد، ولی احساس بی‌نیازی کند.\nفَاسْتَشْفُوهُ مِنْ أَدْوَائِکمْ.\nبرای دردهایی که دارید، از قرآن طلب شفا کنید. قرآن کتابی است که باید شفا را از آن طلب کرد.\n«قُلْ هُوَ لِلَّذِینَ آمَنُوا هُدًی وَشِفَاءٌ، فُصِّلَتْ - ۴۳»\nبدانید قرآن شفای بزرگ‌ترین دردهای بشریت است. از قرآن درمان بگیرید.\nوَاسْتَعِینُوا بِهِ عَلَی لَأْوَائِکمْ.\nاز قرآن استمداد و کمک بگیرید. برای مشکلات کمرشکن، از قرآن طلب عون و یاری بجویید.\nبسیاری از روایات به کاربرد آیه‌ها در درمان دردهای گوناگون اشاره کرده‌اند.\nفَإِنَّ فِیهِ شِفَاءً مِنْ أَکبَرِ الدَّاءِ، وَهُوَ الْکفْرُ وَالنِّفَاقُ وَالْغَی وَالضَّلَالُ.\nدر قرآن، شفای بزرگ‌ترین دردهای شما وجود دارد؛ پس به‌طریق‌اولی، بیماری‌های کوچک را نیز شفا می‌دهد. دردهای طاقت‌فرسا، دردهای باطن و روح هستند که کفر، نفاق، جهل، غیّ و گمراهی از مصادیق آن‌اند.\nمشکل بزرگ جامعه بشری، کفر، شرک و نفاق است که مانند غده‌ای بدخیم، انسان‌ها را تا ابد گرفتار می‌کند.\nفَاسْأَلُوا اللَّهَ بِهِ، وَتَوَجَّهُوا إِلَیهِ بِحُبِّهِ.\nبه قرآن متوسل شوید و حاجات خود را از خداوند، به سبب و توسل به قرآن، بخواهید و بامحبت قرآن به‌سوی خدا روی‌آورید.\nمبادا قرآن را نزد مردم واسطه کنید تا مردم چیزی به شما بدهند. گاهی توسل ما به ائمه علیهم‌السلام، ما را از توسل به قرآن غافل می‌کند. شأن قرآن بالاتر از آن است که با آن کسب درآمد شود. قرآن می‌تواند انسان را به غنا برساند، به‌شرط آنکه قرآن را وسیله درآمد خود نکند.\nمحبت هنگامی خالص است که با اطاعت همراه باشد. اگر کسی ادعای محبت قرآن دارد، باید از آن تبعیت کند. قرآن درباره محبت خداوند به پیامبر می‌فرماید:\n«قُلْ إِنْ کنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِی، آلِ عِمْرَانَ - ۳۱»\nاگر در محبت خود راست‌گو هستید، نشانه آن تبعیت است.\nروایتی از امام صادق علیه‌السلام در کافی، جلد دوم، صفحه ۶۰۷، نقل شده است که مردم چند دسته‌اند:\n۱. قرآن می‌خوانند تا قرائت و صدای آنان مورد تشویق قرار گیرد.\n۲. گروهی قرآن می‌خوانند تا از آن کسب درآمد کنند.\n۳. گروهی قرآن را برای بهره‌بردن می‌خوانند و آن را واسطه هدایت خویش نزد خدا قرار می‌دهند.\nوَلَا تَسْأَلُوا بِهِ خَلْقَهُ، إِنَّهُ مَا تَوَجَّهَ الْعِبَادُ إِلَی اللَّهِ تَعَالَی بِمِثْلِهِ.\nبدانید بندگان به‌جز قرآن، با هیچ‌چیز به خداوند توجه نکرده و به‌سوی او روی نیاورده‌اند. قرآن می‌تواند انسان را محبوب خدا کند.\nصرف محبت کافی نیست.\nوَاعْلَمُوا أَنَّهُ شَافِعٌ مُشَفَّعٌ، وَقَائِلٌ مُصَدَّقٌ.\nبدانید قرآن در قیامت، شفاعت‌گری است که شفاعتش پذیرفته می‌شود و گوینده‌ای است که هرچه بگوید، سخنش در قیامت موردقبول است.\n«وَلَا تَنْفَعُ الشَّفَاعَةُ عِنْدَهُ إِلَّا لِمَنْ أَذِنَ لَهُ، سَبَأ - ۲۲»\nشفاعت هیچ‌کس نزد خدا سودی ندارد، مگر برای کسانی که خداوند به آنان اذن شفاعت داده است.\nوَأَنَّهُ مَنْ شَفَعَ لَهُ الْقُرْآنُ یوْمَ الْقِیامَةِ شُفِّعَ فِیهِ، وَمَنْ مَحَلَ بِهِ الْقُرْآنُ یوْمَ الْقِیامَةِ صُدِّقَ عَلَیهِ.\nاگر قرآن در روز قیامت کسی را شفاعت کند، شفاعتش پذیرفته می‌شود؛ و اگر قرآن از کسی شکایت کند، شکایتش تصدیق و پذیرفته خواهد شد. باتوجه‌به سخنان حضرت، قرآن حقیقتی زنده و موجودی دارای حیات است.\nروایتی در کافی شریف، جلد دوم، صفحه ۶۰۲، آمده است:\nشخصی را برای محاسبه در روز قیامت پیش می‌آورند و طوماری در دست اوست. قرآن با صورتی زیبا پیش می‌آید و می‌گوید: خدایا، من قرآن هستم و این بنده کسی است که خود را برای تلاوت من به‌زحمت می‌انداخت. در شب‌های طولانی قرآن تلاوت می‌کرد. خدایا، خطاهای او را نادیده بگیر؛ زیرا این شخص مرا خشنود کرد.\nفَإِنَّهُ ینَادِی مُنَادٍ یوْمَ الْقِیامَةِ: أَلَا إِنَّ کلَّ حَارِثٍ مُبْتَلًی فِی حَرْثِهِ وَعَاقِبَةِ عَمَلِهِ، غَیرَ حَرَثَةِ الْقُرْآنِ.\nروز قیامت، فرشته‌ای ندا می‌دهد: آگاه باشید که هر کشاورزی که بذری کاشته است، در گرو کِشته و سرانجام عمل خود خواهد بود؛ مگر کسانی که بذر قرآن کاشته‌اند.\nکسی که بذر قرآن را در دل خود می‌کارد، باید با اعمال، رفتار و تبعیت از قرآن، آن را تقویت کند.\nبدانید هر کشاورزی در گرو بذری است که کاشته و فردا همان را درو می‌کند. سعی کنید در سرزمین وجود خود، قرآن را بذرپاشی کرده باشید. تنها کسی که عمل او را بسیار سخت‌گیرانه نمی‌نگرند، کسی است که بذر قرآن را در دل خود کاشته باشد. اگر برخی محصول‌های او پوچ و بی‌ثمر باشد، قرآن کم‌وکاستی آن را اصلاح می‌کند؛ البته به‌شرط آنکه بذر قرآن در دل او کاشته شده باشد؛ زیرا قرآن او را نجات می‌دهد.\nوَاسْتَدِلُّوهُ عَلَی رَبِّکمْ.\nقرآن را راهنما و دلیل خود برای شناخت خدا قرار دهید. اگر کسی سخنی مخالف قرآن گفت، آن را نپذیرید.\nاسْتَنْصِحُوهُ عَلَی أَنْفُسِکمْ.\nدل‌های خود را آماده کنید و از قرآن طلب نصیحت کنید. تکبر، بدخلقی و دیگر صفات خود را به قرآن عرضه کنید و از آن پند بخواهید.\nوَاتَّهِمُوا عَلَیهِ آرَاءَکمْ.\nاگر نظر شما مخالف قرآن بود، اندیشه خود را متهم کنید. تفسیر به رأی نکنید؛ بلکه خود را اصلاح کنید.\nهرگاه فکر و رأی شما با قرآن یکسان نبود و با آن تعارض داشت، رأی خود را متهم کنید و سخن قرآن را بپذیرید؛ زیرا قرآن اشتباه نمی‌گوید.\nوَاسْتَغِشُّوا فِیهِ أَهْوَاءَکمْ.\nاگر هوای نفس، میل و اشتیاق شما با قرآن همسو نبود، میل و طبع خود را کنار بزنید. طبع خود را مغشوش بدانید و سخن قرآن را بگیرید؛ زیرا قرآن خالص است.\nچند روایت درباره قرآن:\nمرحوم کلینی در جلد دوم کافی نقل می‌کند که در روز قیامت، به دستور خداوند، اهل قرآن بالا می‌روند و قرآن به‌صورت موجودی زیبا تجسم می‌یابد. دوستان قرآن نیز که با آن حشرونشر داشتند، زیبا می‌شوند تا به سمت راست عرش می‌رسند.\nخداوند می‌فرماید: قسم به عزت، جبروت و مقام رفیع خودم، ای قرآن، امروز روز تجلی توست. هرکس تو را گرامی داشته باشد، من نیز او را گرامی می‌دارم و هرکس به تو اهانت کرده باشد، او را خوار و خفیف می‌کنم.\nشخصی از امام سجاد علیه‌السلام پرسید: بهترین کار چیست؟ حضرت فرمود: کوچ کردن. آن شخص متوجه نشد. حضرت فرمود: قرائت قرآن از آغاز تا پایان و به‌محض تمام‌شدن، آغاز دوباره آن از ابتدا تا انتها.\nامام صادق علیه‌السلام فرمود: اگر کسی قرآن را با سختی فراگیرد و آن را با مشقت حفظ کند، خداوند به او دو پاداش می‌دهد و پاداشش دوبرابر است.\nمرحوم کلینی از رسول اکرم صلی‌الله علیه و آله نقل می‌کند:\nخانه‌هایتان را با تلاوت قرآن نورانی کنید. مبادا خانه‌های شما به گورستان تبدیل شود. یهود و نصارا چنین بودند که برای نماز و عبادت به مکان‌های خاص می‌رفتند، ولی خانه‌هایشان از عبادت خالی بود؛ ازاین‌رو، خانه‌هایشان تاریک و شبیه گورستان بود. با تلاوت قرآن، خانه را نورانی کنید.\nامام باقر علیه‌السلام فرمود:\nکسانی که با قرآن حشر دارند و قرآن می‌خوانند، سه دسته‌اند:\n۱. آن را کالایی برای کسب اموال می‌دانند.\n۲. آیات را حفظ می‌کنند، ولی حدود آن را ضایع می‌سازند.\n۳. قرآن می‌خوانند تا درد خود را درمان کنند و آن را مایه شفای دل خود قرار می‌دهند. با قرآن شب‌زنده‌داری دارند و تشنگی روز خود را با قرآن برطرف می‌کنند. هرجا محل عبادتشان باشد، قرآن را در کنار خود قرار می‌دهند. خداوند به برکت آنان بلا را دفع می‌کند و به برکت آنان باران می‌بارد. این‌گونه قاریان از کبریت احمر و از هر گوهر نایابی، کمیاب‌تر هستند.\nغَفَرَ اللَّهُ لِی وَلَکمْ، اللَّهُمَّ نَوِّرْ قُلُوبَنَا بِالْقُرْآنِ.\nسؤال: قرآن استیجاری اشکال دارد؟\nدو نکته درباره این سؤال وجود دارد:\nاولاً شأن فقه و اخلاق متفاوت است. حضرت در مسائل اخلاقی می‌فرمایند از قرآن کسب درآمد نکنید، ولی همین مسئله از نظر فقهی بی‌اشکال است.\nبرای مثال، خوردن غذای گرم و لذیذ در برابر کودک فقیر و گرسنه‌ای که با حسرت نگاه می‌کند، از جهت فقهی بی‌اشکال است؛ ولی از جهت اخلاقی مشکل دارد.\nثانیاً اگر انسان هنگام قرائت استیجاری، متوجه آیات باشد و قصد عمل‌کردن به آن‌ها را داشته باشد، آن بحث اخلاقی نیز اشکالی نخواهد داشت و غرض انسان، عمل به قرآن می‌شود.\nمانند شخص منبری که در ماه مبارک برای مردم تفسیر قرآن می‌گوید و غرض او هدایت مردم است؛ ولی اگر مبلغی نیز به‌عنوان حق‌الزحمه به او بدهند، ایرادی ندارد.","بخش سوم\nمتن:\nالحَثُّ على العمل:\nالْعَمَلَ الْعَمَلَ، ثُمَّ النِّهَايَةَ النِّهَايَةَ، وَ الِاسْتِقَامَةَ الِاسْتِقَامَةَ، ثُمَّ الصَّبْرَ الصَّبْرَ، وَ الْوَرَعَ الْوَرَعَ. إِنَّ لَكُمْ نِهَايَةً فَانْتَهُوا إِلَى نِهَايَتِكُمْ، وَ إِنَّ لَكُمْ عَلَماً فَاهْتَدُوا بِعَلَمِكُمْ، وَ إِنَّ لِلْإِسْلَامِ غَايَةً فَانْتَهُوا إِلَى غَايَتِهِ، وَ اخْرُجُوا إِلَى اللَّهِ بِمَا افْتَرَضَ عَلَيْكُمْ مِنْ حَقِّهِ وَ بَيَّنَ لَكُمْ مِنْ وَظَائِفِهِ، أَنَا شَاهِدٌ لَكُمْ وَ حَجِيجٌ يَوْمَ الْقِيَامَةِ عَنْكُمْ.\nأَلَا وَ إِنَّ الْقَدَرَ السَّابِقَ قَدْ وَقَعَ وَ الْقَضَاءَ الْمَاضِيَ قَدْ تَوَرَّدَ، وَ إِنِّي مُتَكَلِّمٌ بِعِدَةِ اللَّهِ وَ حُجَّتِهِ، قَالَ اللَّهُ [جَلَّ ذِكْرُهُ] تَعَالَى \"إِنَّ الَّذِينَ قالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخافُوا وَ لا تَحْزَنُوا وَ أَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ\"، وَ قَدْ قُلْتُمْ رَبُّنَا اللَّهُ، فَاسْتَقِيمُوا عَلَى كِتَابِهِ وَ عَلَى مِنْهَاجِ أَمْرِهِ وَ عَلَى الطَّرِيقَةِ الصَّالِحَةِ مِنْ عِبَادَتِهِ، ثُمَّ لَا تَمْرُقُوا مِنْهَا وَ لَا تَبْتَدِعُوا فِيهَا وَ لَا تُخَالِفُوا عَنْهَا، فَإِنَّ أَهْلَ الْمُرُوقِ مُنْقَطَعٌ بِهِمْ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ.\nثُمَّ إِيَّاكُمْ وَ تَهْزِيعَ الْأَخْلَاقِ وَ تَصْرِيفَهَا، وَ اجْعَلُوا اللِّسَانَ وَاحِداً وَ لْيَخْزُنِ الرَّجُلُ لِسَانَهُ، فَإِنَّ هَذَا اللِّسَانَ جَمُوحٌ بِصَاحِبِهِ، وَ اللَّهِ مَا أَرَى عَبْداً يَتَّقِي تَقْوَى تَنْفَعُهُ حَتَّى [يَخْتَزِنَ] يَخْزُنَ لِسَانَهُ، وَ إِنَّ لِسَانَ الْمُؤْمِنِ مِنْ وَرَاءِ قَلْبِهِ وَ إِنَّ قَلْبَ الْمُنَافِقِ مِنْ وَرَاءِ لِسَانِهِ، لِأَنَّ الْمُؤْمِنَ إِذَا أَرَادَ أَنْ يَتَكَلَّمَ بِكَلَامٍ تَدَبَّرَهُ فِي نَفْسِهِ، فَإِنْ كَانَ خَيْراً أَبْدَاهُ وَ إِنْ كَانَ شَرّاً وَارَاهُ؛ وَ إِنَّ الْمُنَافِقَ يَتَكَلَّمُ بِمَا أَتَى عَلَى لِسَانِهِ، لَا يَدْرِي مَا ذَا لَهُ وَ مَا ذَا عَلَيْهِ؛ وَ لَقَدْ قَالَ رَسُولُ اللَّهِ (صلی الله علیه وآله) لَا يَسْتَقِيمُ إِيمَانُ عَبْدٍ حَتَّى يَسْتَقِيمَ قَلْبُهُ وَ لَا يَسْتَقِيمُ قَلْبُهُ حَتَّى يَسْتَقِيمَ لِسَانُهُ. فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَلْقَى اللَّهَ تَعَالَى وَ هُوَ نَقِيُّ الرَّاحَةِ مِنْ دِمَاءِ الْمُسْلِمِينَ وَ أَمْوَالِهِمْ سَلِيمُ اللِّسَانِ مِنْ أَعْرَاضِهِمْ، فَلْيَفْعَلْ.\nترجمه:\nعمل کنيد، عمل کنيد ; سپس به پايان رسانيد، به پايان رسانيد، اعتدال، اعتدال ; سپس شکيبايى، شکيبايى ; و پارسايى، پارسايى. (بدانيد) براى شما پايان و مقصدى است ; خود را به آن برسانيد و براى شما نشانه اى قرار داده شده; به وسيله آن راه را پيدا کنيد و اسلام هدفى دارد به هدف آن برسيد. با انجام دادن فرايضى که خدا بر شماست و وظايفى که براى شما تبيين کرده، حق او را ادا کنيد که (اگر چنين کنيد) من مدافع شما در روز قيامت خواهم بود!\nآگاه باشيد! مقدّرات پيشين به وقوع پيوست و قضاى (الهى) انجام يافت (و سرانجام خلافت به اهلش رسيد) و من به اتکاى وعده هاى الهى و با دليل و حجت او سخن مى گويم. خداوند مى فرمايد: کسانى که گفتند: پروردگار ما خدا است، سپس در مسير مستقيم، ثابت ماندند، فرشتگان الهى بر آن ها نازل مى شوند (و به آن ها مى گويند:) نترسيد، اندوهگين مباشيد و بشارت باد بر شما به آن بهشتى که به شما وعده داده مى شد. شما گفته ايد: پروردگار ما خداست; بنابراين بايد بر طريقه کتاب او و راه روشن فرمانش و مسير درست عبادتش مستقيم و ثابت بمانيد. سپس از اين مسير روشن خارج نشويد و در آن بدعتى نگذاريد و از آن منحرف نگرديد ; چه اين که آنان که خارج شوند در قيامت در پيشگاه خدا وا مى مانند و به سر منزل مقصود نمى رسند.\nسپس برحذر باشيد از درهم شکستن فضايل اخلاقى و دگرگون ساختن آن. يک زبان باشيد (و هميشه حق بگوييد) انسان بايد زبان خود را نگه دارد; زيرا اين زبان، سرکش است و صاحبش را به هلاکت مى افکند. به خدا سوگند! باور نمى کنم بنده اى که زبانش را حفظ نکند، به درجه اى از تقوا برسد که به حالش سودمند گردد، (بدانيد،) زبان مؤمن، پشت قلب او قرار دارد و قلب منافق، پشت زبان اوست ; چون مؤمن هرگاه بخواهد سخنى بگويد نخست مى انديشد; اگر خير بود اظهار مى کند و اگر شرّ بود آن را پنهان مى سازد ; ولى منافق آن چه بر زبانش جارى مى شود مى گويد ; در حالى که نمى داند کدام به سود اوست و کدام به زيان او. رسول خدا(صلى الله عليه وآله) فرمود: ايمان هيچ بنده اى صاف و استوار نخواهد شد تا قلبش صاف شود و هيچ گاه قلبش صاف و استوار نخواهد شد تا زبانش چنين گردد. هر کس از شما بتواند خدا را در حالى ملاقات کند که دستش از خون و اموال مسلمانان پاک باشد و زبانش از تعدى بر آبروى آنان سالم بماند، بايد چنين کند (که نجات در آن است).\nتفسیر:\nدر مسیر سیروسلوک، مؤمن به سه کار می‌پردازد.\nوَاعْلَمُوا عِبَادَ اللَّهِ أَنَّ الْمُؤْمِنَ لَا یمْسِی وَلَا یصْبِحُ إِلَّا وَنَفْسُهُ ظَنُونٌ عِنْدَهُ.\n۱. انسان مؤمن صبح و شب را سپری نمی‌کند، مگر آنکه نفس خود را متهم می‌کند.\nبه‌جای سوءظن به دیگران، روز و شب خود را با سوءظن به نفس خویش سپری می‌کند.\nما باید نسبت به همه حسن‌ظن داشته باشیم. اصل بر خوب‌بودن دیگران است، مگر آنکه خلاف آن ثابت شود؛ اما در مورد خود، نباید نگاه رضایت‌مندانه داشت، بلکه باید با دیده اتهام به نفس نگریست.\nفَلَا یزَالُ زَارِیا عَلَیهَا.\n۲. مؤمن پیوسته از نفس خود عیب‌جویی و کنکاش می‌کند. عیب‌جویی از دیگران بسیار ناپسند است؛ ولی انسان باید همواره با ذره‌بین در پی عیب‌های خود باشد.\nوَمُسْتَزِیدًا لَهَا.\n۳. مؤمن نه‌تنها عیب را اصلاح می‌کند، بلکه مرتبه‌ای بالاتر، خواهان افزونی نیز هست.\nخوبی، خیر و صلاح را برای نفس خود طلب می‌کند و برای تکامل آن‌ها می‌کوشد. رشد و حرکت، یا کند است یا تند؛ یا سبقت است یا سرعت، ولی ایستایی ندارد.\nفَکونُوا کالسَّابِقِینَ قَبْلَکمْ وَالْمَاضِینَ أَمَامَکمْ.\nبه گذشتگان و سلف صالح خود توجه کنید.\nحضرت مطلقاً هر سلفی را نمی‌فرماید، بلکه مقصود، سلف مؤمن و صالحی است که شایستگی پیروی دارند؛ یا مؤمنان نزدیکی که پیش از شما بودند و از دنیا رفتند. به مرگ و رفتن آنان توجه کنید. کافران به‌اشتباه گفتند:\n«وَإِذَا قِیلَ لَهُمُ اتَّبِعُوا مَا أَنْزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَینَا عَلَیهِ آبَاءَنَا، بَقَرَة - ۱۷۰»\nهنگامی که به آنان گفته می‌شد از آنچه خدا نازل کرده است پیروی کنید، می‌گفتند: ما از آنچه پدران خود را بر آن یافته‌ایم، پیروی می‌کنیم.\nحضرت می‌فرماید: مانند پدران و اجداد مؤمن خود باشید؛ زیرا آنان شایستگی پیروی دارند.\nقَوَّضُوا مِنَ الدُّنْیا تَقْوِیضَ الرَّاحِلِ.\nویژگی دیگر این اجداد مؤمن که باید در این زمینه از آنان الگو بگیریم، این بود که علم و ستون خیمه دنیا را از دل خود کنده بودند.\nدلبسته دنیا نبودند و در دنیا مانند مسافری موقت، آماده کوچ به سرای آخرت بودند.\nوَطَوَوْهَا طَی الْمَنَازِلِ.\nدنیا را مانند کسانی طی کردند که در میان راه، منزلی را انتخاب می‌کنند و سپس به‌سرعت از آن می‌گذرند.\nامیرالمؤمنین سلام‌الله‌علیه در بحث مواظبت بر عمل به قرآن فرمود:\nالْعَمَلَ الْعَمَلَ.\nبه دستورهای دین و قرآن عمل کنید.\nثُمَّ النِّهَایةَ النِّهَایةَ.\nکار را در میانه راه رها نکنید؛ آن را تا سرحد نهایت پیش ببرید و به پایان برسانید.\nوَالِاسْتِقَامَةَ الِاسْتِقَامَةَ.\nاگر در راهی هستید، با آن راه ملازم باشید و هرگز از آن جدا نشوید.\nثُمَّ الصَّبْرَ الصَّبْرَ.\nاین مسیر سختی دارد و نیازمند صبوری است.\nوَالْوَرَعَ الْوَرَعَ.\nدر انجام و مراقبت از عمل، ورع داشته باشید.\nاز این پنج توصیه، سه مورد مربوط به کار و تلاش است. در مسیر عمل، سه مرحله «عمل، نهایت و صبر» وجود دارد و دو بخش دیگر، کیفیت عمل را بیان می‌کند.\nرساندن کار به هدف، دشوار است و باید زحمت کشید تا اعمال به‌درستی انجام گیرند.\nاستقامت، کیفیت رسیدن به نهایت است.\nصبر، از مراحل سه‌گانه عمل، نیازمند مراتب بالای تقواست که همان ورع است.\nورع نیز کیفیت صبر است. صبوری با تقوای معمولی امکان‌پذیر نیست؛ زیرا در بسیاری از موارد، هوس پیش می‌آید. با اوج تقوا که همان ورع است، می‌توان به صبوری دست‌یافت.\nإِنَّ لَکمْ نِهَایةً فَانْتَهُوا إِلَی نِهَایتِکمْ.\nبرای شما مقصد و هدفی از خلقت وجود دارد که برای آن آفریده شده‌اید.\nدر مسیر زندگی شما پایانی هست؛ به‌سوی همان نقطه حرکت کنید.\nوَإِنَّ لَکمْ عَلَمًا فَاهْتَدُوا بِعَلَمِکمْ.\nدر میانه راه نیز نشانه‌هایی وجود دارد؛ قرآن، امام، انبیا و اولیا. به سبب آن‌ها راهنمایی بگیرید تا راه درست را از بیراهه تشخیص دهید.\nوَإِنَّ لِلْإِسْلَامِ غَایةً فَانْتَهُوا إِلَی غَایتِهِ.\nبرای اسلام و دین نیز غایتی وجود دارد. شما یک وظیفه فردی و یک وظیفه اجتماعی دارید.\nدین برای جامعه نیز هدفی دارد.\nشما با انجام وظایف اجتماعی خود باید برای به ثمر رساندن آن حرکت کنید. جامعه را باید به جایی برسانید.\nدل‌مشغولی، مانع رسیدن به هدف است. از این شاخه به آن شاخه پریدن چاره‌ساز نیست. با تمام قوا و با تمرکز کامل، در یک مسیر پیش بروید.\nشیخ بهایی که در علوم گوناگون، چه علوم دینی و چه علوم غیردینی مانند معماری، صاحب‌نظر بود، می‌گوید: هرکس صاحب فنون گوناگون بود، بر او چیره شدم؛ اما مغلوب کسانی شدم که تنها یک فن داشتند؛ زیرا همه تمرکز خود را در همان مسیر گذاشته بودند.\nمقصد اسلام کجاست؟ هدف مسلمانی چیست؟ اگر خود را با این هدف نسنجیم، به هرجا برسیم، همان را پایان کار می‌پنداریم.\nاگر غایت اسلام تنها گفتن شهادتین باشد، ثمره آن پاک‌شدن بدن از نجاست و دفن شدن در قبرستان مسلمانان است؛ ولی انسان را به قرب الهی نمی‌رساند. هدف فقط شهادتین نبوده است. اهداف بلندی در نظر گرفته شده است و باید با اخلاق‌مداری در آن مسیر تلاش و حرکت کرد.\nاز اهداف اسلام، تشکیل حکومت اسلامی است.\nاهداف جمعی و اجتماعی را باید پیش برد.\nپس هر فرد در دو میدان مبارزه نقش دارد:\nالف. مبارزه فرد با خود و مبارزه درونی.\nب. مبارزه برای اصلاح جامعه و مبارزه بیرونی.\nمبادا از دین خدا خارج شوید.\nباید این دو وظیفه را به‌خوبی انجام دهید تا خدا شما را از این ذمه بری کند و پای شما گرفتار نباشد.\nوَأَخْرِجُوا إِلَی اللَّهِ مِمَّا افْتَرَضَ عَلَیکمْ مِنْ حَقِّهِ وَبَینَ لَکمْ مِنْ فَرَائِضِهِ.\nبه‌سوی آنچه بر شما واجب شده است حرکت کنید و ذمه خود را بری سازید.\nمبادا هنگام رفتن از دنیا، کوهی از اعمال واجب بر گردن شما باشد که معطل‌مانده و انجام نشده باشد. فرائضی را که برای شما مشخص کرده‌اند، انجام دهید.\nأَنَا شَاهِدٌ لَکمْ وَحَجِیجٌ یوْمَ الْقِیامَةِ عَنْکمْ.\nاین جمله‌ای دلگرم‌کننده از امیرالمؤمنین صلوات‌الله‌علیه است: من شاهد شما هستم و گواهی می‌دهم که چقدر در راه دین زحمت کشیده‌اید. در روز قیامت از شما دفاع و برای شما حجت می‌آورم که برای اصلاح نفس تلاش کرده و خون‌جگر خورده‌اید.\nاینکه انسان با تک‌ماده و ارفاق وارد بهشت شود، کجا؛ و اینکه حضرت در برابر ملائکه سینه سپر کند و بگوید فلان شخص درست عمل کرده و هدف خلقت را رعایت کرده است، کجا؟ تفاوت بسیار است.\nحضرت باید به این افتخار کند که ما شیعه او هستیم.\n«عَلِی ضَامِنٌ لِفَلَجِکمْ»\nپیروزی شما را در دنیا و آخرت ضمانت می‌کنم.\nأَلَا وَإِنَّ الْقَدَرَ السَّابِقَ قَدْ وَقَعَ.\nبدانید مقدرات پیشینی که خداوند رقم زده بود، واقع شد.\nاین عبارت به جریان‌های پس از پیامبر اشاره دارد.\nبنا بود اتفاقاتی رخ دهد و عده‌ای ظلم و غصب کنند. همه این امور واقع شد و گذشت.\nوَالْقَضَاءَ الْمَاضِی قَدْ تَوَارَدَ.\nبرنامه‌ای که خدا چیده بود، یکی‌یکی و پشت‌سرهم تحقق یافت. همه چیز طبق اراده الهی پیش می‌رود.\nاراده الهی با اختیار انسان منافات ندارد. اگر خدا قضاوقدر الهی را نوشته باشد، به این معنا نیست که ما مجبور به انجام آن هستیم؛ هرگز چنین نیست.\nخدا اراده کرده است که انسان هرگونه بخواهد، اراده کند؛ بنابراین، هر فعلی که از او صادر می‌شود، همراه با خواست اوست و باید پاسخ‌گو باشد که چرا و به چه دلیل آن کار را انجام داده است.\nانسان باید پاسخ‌گو باشد؛ درعین‌حال که اراده خدا وجود دارد، اختیار و اراده انسان نیز وجود دارد.\nوَإِنِّی لَمُتَکلِّمٌ بِعِدَةِ اللَّهِ وَحُجَّتِهِ.\nمن که با شما سخن می‌گویم، وعده‌های الهی درباره من محقق می‌شود.\nدست من پر است و خبرهایی دارم که این‌گونه با شما سخن می‌گویم. حجت‌هایی دارم که با آن‌ها ادعای خود را ثابت می‌کنم.\nقَالَ اللَّهُ تَعَالَی: «إِنَّ الَّذِینَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَیهِمُ الْمَلَائِکةُ أَنْ لَا تَخَافُوا وَلَا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِی کنْتُمْ تُوعَدُونَ، فُصِّلَت - ۳۰»\nمؤمنانی که گفتند: خدا پروردگار ماست و بر این راه محکم ایستادند، فرشتگان بر آنان نازل می‌شوند و می‌گویند: نترسید و اندوهگین نباشید.\nآنان را به بهشت خوش‌آب‌ورنگی که وعده‌داده‌شده بود، بشارت می‌دهند.\nحضرت از این آیه استفاده کردند.\nشما که گام نخست، یعنی «رَبُّنَا اللَّهُ» را گفته‌اید، به مرتبه نخست ایمان رسیده‌اید. تنها یک گام باقی‌مانده است: در مرتبه بعد، بر کتاب خدا و راه‌وروش اوامر الهی استقامت بورزید و استوار بمانید.\nمجمع‌البیان مرحوم طبرسی، ذیل این آیه، استقامت را به ولایت تفسیر کرده است.\nاز امام هشتم سؤال شد که استقامت در این آیه چیست تا اگر آن را انجام دادیم، مشمول آن شویم؟ حضرت فرمود:\n«هِی وَاللَّهِ مَا أَنْتُمْ عَلَیهِ»\nاستقامت یعنی اهل ولایت علی و اولاد علی باشید و از آنان اطاعت کنید تا مرتبه استقامت شامل حال شما شود.\nوَقَدْ قُلْتُمْ رَبُّنَا اللَّهُ فَاسْتَقِیمُوا عَلَی کتَابِهِ، وَعَلَی مِنْهَاجِ أَمْرِهِ، وَعَلَی الطَّرِیقَةِ الصَّالِحَةِ مِنْ عِبَادَتِهِ.\nاین سه مرحله را رعایت کنید تا گام دوم نیز محقق شود. بر کتاب خدا استقامت کنید، به راه‌وروش قرآن عمل کنید و در راه خدا قدم بردارید.\n۱. عقاید.\n۲. احکام.\n۳. اخلاق.\nاین سه مرحله را انجام دهید تا به جایی برسید که فرشتگان بر شما نازل شوند و به همان بهشت وعده‌داده‌شده برسید.\nثُمَّ لَا تَمْرُقُوا مِنْهَا، وَلَا تَبْتَدِعُوا فِیهَا، وَلَا تُخَالِفُوا عَنْهَا.\nاین سه مسیر بسیار آسان نیست. سه خطر بر سر راه پویندگان حق وجود دارد.\nاین سه پله‌ای که باید طی کنید، سه‌راه انحرافی نیز دارد. سه چاه در برابر آن سه‌راه قرار گرفته است.\n۱. از کتاب، اوامر الهی و طریق صالحه خارج نشوید.\nکسانی بودند که ابتدا گفتند «رَبُّنَا اللَّهُ»، ولی از راه خارج شدند و در برابر علی ایستادند.\n۲. دومین راه انحرافی این است که در این مسیر بدعت‌گذار نباشید.\n۳. با این مسیر مخالفت نکنید.\nتفاوت انحراف اول و سوم این است که در خروج، انسان ممکن است اهل نماز و روزه باشد، ولی به بهشت و دوزخ اعتقاد نداشته باشد.\nانحراف سوم، یعنی مخالفت‌کردن، همان ارتداد، شمشیر کشیدن و اعلام جنگ است.\nفَإِنَّ أَهْلَ الْمُرُوقِ مُنْقَطَعٌ بِهِمْ عِنْدَ اللَّهِ یوْمَ الْقِیامَةِ.\nکسانی که قدم از این راه بیرون گذاشته‌اند، در روز قیامت به رحمت خدا راه ندارند.\nثُمَّ إِیاکمْ وَتَهْزِیعَ الْأَخْلَاقِ وَتَصْرِیفَهَا.\nپس از بیان کلیات اخلاق، رفع موانع و عیب شناسی، حضرت بر یک مانع بزرگ انگشت می‌گذارد.\nآن مانع و گرفتاری بزرگ این است:\nپس برحذر باشید از درهم شکستن اخلاق. احترام کوچک‌تر به بزرگ‌تر، امری فطری است؛ ولی عده‌ای آن را چنان شکسته و زیر پا نهاده‌اند که این اصل از بین رفته است.\nمبادا تغییر و اضطراب در اخلاق پدید آید. مبادا اصول اخلاقی را از بین ببرید و به‌طورکلی نابود کنید یا آن‌ها را دگرگون سازید.\nدر جامعه گاهی اخلاق از بین می‌رود و گاهی اخلاق وجود دارد، اما اسلامی نیست.\nاخلاقی دست‌وپاشکسته وجود دارد؛ اخلاقی که در آن حرمت پدر و مادر، حق استاد و معلم، حق ولی و حق زحمت‌کشان رعایت نمی‌شود.\nاخلاق، مجموعه‌ای کامل است. اگر یک جزء از این مجموعه برداشته شود، نابود شده است؛ مانند نماز که اگر یک جزء آن، یعنی سجده، حذف شود، دیگر آن نماز چگونه خواهد بود؟\nصحت نماز به صحت همه اجزای آن وابسته است، نه به تک‌تک آن‌ها به‌صورت جداگانه.\nاخلاق نیز مجموعه‌ای به‌هم‌پیوسته است.\nاگر می‌خواهید کامروا شوید، باید همه آن را حفظ کنید.\nاصرار بر چهار مورد اخلاقی و بی‌توجهی به چهار مورد دیگر، نابودی اخلاق است.\nوَاجْعَلُوا اللِّسَانَ وَاحِدًا.\nیک نمونه از اخلاق، زبان است.\nزبانتان را واحد قرار دهید. همان‌گونه که یک‌دل هستید، یک‌زبان نیز باشید. صفت منافق، دوزبانی است؛ ظاهر و باطن او یکی نیست.\n«وَإِذَا لَقُوا الَّذِینَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا إِلَی شَیاطِینِهِمْ قَالُوا إِنَّا مَعَکمْ إِنَّمَا نَحْنُ مُسْتَهْزِئُونَ، بَقَرَة - ۱۵»\nهنگامی که مؤمنان را ملاقات می‌کنند، می‌گویند: ایمان آورده‌ایم؛ اما وقتی با هم‌کیشان خود خلوت می‌کنند، به آنان می‌گویند: ما با شماییم و مؤمنان را به استهزا گرفته‌ایم.\nوَلْیخْزُنِ الرَّجُلُ لِسَانَهُ.\nهرکس باید زبان خود را در خزینه نگه دارد و نگهبان زبان خویش باشد. زبان نباید آزاد باشد؛ زبان درنده است. اگر آن را رها کنید، گاز می‌گیرد.\nفَإِنَّ هَذَا اللِّسَانَ جَمُوحٌ بِصَاحِبِهِ.\nاگر از زبان مراقبت نشود، این زبان چموش، مانند اسب، صاحب خود را به زمین می‌زند. زبان می‌تواند حقیقت و شخصیت انسان را نابود کند. بر زبان چموش سوار نشوید؛ زیرا مرکب خوبی نیست.\nتشبیه زبان به اسب چموش، بسیار لطیف است. زبان مدام در دهان در حال چرخش، بالا و پایین‌رفتن، راست و چپ شدن و پیچ‌وخم خوردن است تا لفظ ادا شود. زبان در پی لحظه‌ای است که غفلت پیش آید تا دروغ بگوید، خیانت کند و آبرو ببرد.\nوَاللَّهِ مَا أَرَی عَبْدًا یتَّقِی تَقْوًی تَنْفَعُهُ حَتَّی یخْزُنَ لِسَانَهُ.\nبه خدا قسم، تقوای سودمندی در کسی ندیدم، مگر آنکه زبان خود را به غل‌وزنجیر کشیده باشد.\nبعید است کسی به تقوا دست یابد، درحالی‌که پیش از آن زبانش مهر نشده باشد. اگر زبان رها باشد، آبرو، حیثیت و حتی دین انسان را در اختیار خود می‌گیرد.\nوَإِنَّ لِسَانَ الْمُؤْمِنِ مِنْ وَرَاءِ قَلْبِهِ.\nزبان مؤمن پشت قلب اوست. قلب در اینجا به معنای عقل و فکر است.\nلِأَنَّ الْمُؤْمِنَ إِذَا أَرَادَ أَنْ یتَکلَّمَ بِکلَامٍ تَدَبَّرَهُ فِی نَفْسِهِ.\nمؤمن ابتدا درباره سخنی که می‌خواهد بگوید، تفکر و بررسی می‌کند و سپس سخن می‌گوید.\nفَإِنْ کانَ خَیرًا أَبْدَاهُ، وَإِنْ کانَ شَرًّا وَارَاهُ.\nاگر کلام خوب باشد و سبب خوشحالی کسی شود، آن را آشکار می‌کند؛ اما اگر سخن مشکل‌ساز باشد، باعث رنجش دل شود یا اسراری را فاش کند، آن را پنهان می‌سازد.\nوَإِنَّ الْمُنَافِقَ مِنْ وَرَاءِ لِسَانِهِ، یتَکلَّمُ بِمَا أَتَی عَلَی لِسَانِهِ، لَا یدْرِی مَاذَا لَهُ وَمَاذَا عَلَیهِ.\nقلب منافق پشت زبان اوست.\nهرچه بر زبانش آید، می‌گوید. نمی‌داند کدام‌یک از سخنانش به سود اوست، کدام به زیان اوست و کدام سخن، دین او را حفظ می‌کند. نفاق به این امور کاری ندارد و تنها سخن را بر زبان جاری می‌کند.\nوَلَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیهِ وَآلِهِ: لَا یسْتَقِیمُ إِیمَانُ عَبْدٍ حَتَّی یسْتَقِیمَ قَلْبُهُ.\nایمان بنده اصلاح و نورانی نمی‌شود، مگر آنکه قلب او اصلاح شود. یعنی ایمان در گرو قلب است. قلب است که ایمان را تقویت می‌کند. زبان بر قلب انسان و قلب بر ایمان او تأثیر دارد.\nوَلَا یسْتَقِیمُ قَلْبُهُ حَتَّی یسْتَقِیمَ لِسَانُهُ.\nقلب نیز اصلاح نمی‌شود، مگر با اصلاح زبان.\nاین زبان است که می‌تواند قلب را جلا دهد یا بر آن زنگار بنشاند.\nقرآن درباره رابطه قلب و زبان می‌فرماید:\n«یا أَیهَا الَّذِینَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِیدًا یصْلِحْ لَکمْ أَعْمَالَکمْ … فَقَدْ فَازَ فَوْزًا عَظِیمًا، أَحْزَاب - ۷۰»\nای مؤمنان، تقوای الهی را رعایت کنید و سخنی استوار بگویید. تقوای زبان داشته باشید. سخن شما باید متقن و محکم باشد. بدون سند و پشتوانه و از روی هواوهوس، سخنی نگویید.\nتقوای زبان و حفظ آن، اعمال شما را اصلاح می‌کند.\nوقتی قلب اصلاح شد، ایمان نیز درست می‌شود.\nفَمَنِ اسْتَطَاعَ مِنْکمْ أَنْ یلْقَی اللَّهَ سُبْحَانَهُ.\nهرکس از شما می‌تواند خداوند سبحان را با این سه حالت ملاقات کند، باید در آن کوتاهی نکند.\nوَهُوَ نَقِی الرَّاحَةِ مِنْ دِمَاءِ الْمُسْلِمِینَ.\n۱. تا می‌توانید دست خود را از خون مسلمانان پاک نگه دارید و بر آن بکوشید تا خدا را ملاقات کنید.\nوَأَمْوَالِهِمْ.\n۲. تا می‌توانید دست خود را از اموال مسلمانان دورنگه دارید و به بیت‌المال دست‌درازی نکنید.\nسَلِیمُ اللِّسَانِ مِنْ أَعْرَاضِهِمْ فَلْیفْعَلْ.\n۳. زبان خود را از آبروی مسلمانان حفظ کنید و تا می‌توانید چنین رفتار کنید.\nاز قول صادق آل محمد صلی‌الله علیه و آله:\n«اَلْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ یدِهِ وَلِسَانِهِ»\nمسلمان کسی است که مردم، نه‌فقط مؤمنان، از دست و زبان او در آرامش باشند. حتی اگر آن انسان یهودی یا گبر باشد، باید در امنیت باشد.\nاللَّهُمَّ اجْعَلْ لَنَا لِسَانَ صِدْقٍ عَلِیا.","بخش چهارم\nمتن:\nتحريم البِدَع:\nوَ اعْلَمُوا عِبَادَ اللَّهِ أَنَّ الْمُؤْمِنَ يَسْتَحِلُّ الْعَامَ مَا اسْتَحَلَّ عَاماً أَوَّلَ، وَ يُحَرِّمُ الْعَامَ مَا حَرَّمَ عَاماً أَوَّلَ، وَ أَنَّ مَا أَحْدَثَ النَّاسُ لَا يُحِلُّ لَكُمْ شَيْئاً مِمَّا حُرِّمَ عَلَيْكُمْ، وَ لَكِنَّ الْحَلَالَ مَا أَحَلَّ اللَّهُ وَ الْحَرَامَ مَا حَرَّمَ اللَّهُ. فَقَدْ جَرَّبْتُمُ الْأُمُورَ وَ ضَرَّسْتُمُوهَا وَ وُعِظْتُمْ بِمَنْ كَانَ قَبْلَكُمْ وَ ضُرِبَتِ الْأَمْثَالُ لَكُمْ وَ دُعِيتُمْ إِلَى الْأَمْرِ الْوَاضِحِ، فَلَا يَصَمُّ عَنْ ذَلِكَ إِلَّا أَصَمُّ وَ لَا يَعْمَى عَنْ ذَلِكَ إِلَّا أَعْمَى، وَ مَنْ لَمْ يَنْفَعْهُ اللَّهُ بِالْبَلَاءِ وَ التَّجَارِبِ، لَمْ يَنْتَفِعْ بِشَيْءٍ مِنَ الْعِظَةِ، وَ أَتَاهُ التَّقْصِيرُ مِنْ أَمَامِهِ، حَتَّى يَعْرِفَ مَا أَنْكَرَ وَ يُنْكِرَ مَا عَرَفَ. [فَإِنَّ النَّاسَ] وَ إِنَّمَا النَّاسُ رَجُلَانِ: مُتَّبِعٌ شِرْعَةً، وَ مُبْتَدِعٌ بِدْعَةً، لَيْسَ مَعَهُ مِنَ اللَّهِ سُبْحَانَهُ بُرْهَانُ سُنَّةٍ وَ لَا ضِيَاءُ حُجَّةٍ.\nالقرآن:\n[فَإِنَ] وَ إِنَّ اللَّهَ سُبْحَانَهُ لَمْ يَعِظْ أَحَداً بِمِثْلِ هَذَا الْقُرْآنِ، فَإِنَّهُ حَبْلُ اللَّهِ الْمَتِينُ وَ سَبَبُهُ الْأَمِينُ، وَ فِيهِ رَبِيعُ الْقَلْبِ وَ يَنَابِيعُ الْعِلْمِ وَ مَا لِلْقَلْبِ جِلَاءٌ غَيْرُهُ، مَعَ أَنَّهُ قَدْ ذَهَبَ الْمُتَذَكِّرُونَ وَ بَقِيَ النَّاسُونَ أَوِ الْمُتَنَاسُونَ؛\nترجمه:\nبدانيد اى بندگان خدا! انسان با ايمان آن چه را سال گذشته حلال مى شمرد، امسال هم حلال مى شمرد و آن چه را سال گذشته حرام مى دانست امسال هم حرام مى داند (بدانيد) بدعت هايى را که مردم گذارده اند آن چه را بر شما حرام شده، حلال نمى کند; حلال همان است که خدا حلال کرده و حرام همان است که خدا حرام نموده، شما امور مختلف را (در مورد بدعت ها) آزموده ايد و خوب و بد را در اين تجربه آموخته ايد و با وضع گذشتگان پند و اندرز داده شده ايد، عبرت گرفته ايد و مَثَل ها براى شما زده شده و به امرى آشکار دعوت شده ايد. بر اين اساس، تنها افراد ناشنوا از درک اين مطلب عاجز و ناتوانند و تنها نابينايان آن نمى بينند.\n(بدانيد) آن کس که از آزمون هاى الهى وتجربه ها، سودى نبرد، از هيچ پند و اندرزى سود نخواهد برد و کوته فکرى و کوته بينى، آشکارا دامان او را مى گيرد ; تا آن جا که بد را خوب و خوب را بد مى بيند. مردم دو گروه بيش نيستند ; گروهى تابع شريعت و آيين خدا و گروهى بدعت گزار که دليلى از سوى خدا و از سنّت پيامبر و نورى از حجّت و دليل (عقل) با خود ندارند!\nخداوند سبحان، احدى را به چيزى مانند قرآن، پند و اندرز نداده است; زيرا قرآن رشته محکم خدا و وسيله مطمئن اوست. در قرآن، بهار دل ها و چشمه هاى جوشان علم و دانش است و براى (زدودن زنگار غفلت وگناه از) قلب، صيقلى جز قرآن نيست; اما متأسفانه آن ها که از قرآن پند مى گرفتند رفتند و فراموشکاران يا خود به فراموشى زدگان مانده اند.\nتفسیر:\n   بحث بدعت‌گذاری\n♦️وَاعْلَمُوا عِبَادَِلُّ الْ إِنَّ الْمُؤْمِنَ یسْتَحِلُّ الْعَامَ مَا اسْتَحَلَّ عَامًا أَوَّلَ\nبدانید؛ مؤمن کسی است که حلالِ امسال را حلال می‌شمارد، همان‌طور که سالِ قبل آن را حلال می‌دانست.\n♦️وَیحَرِّمُ الْعَامَ مَا حَرَّمَ عَامًا أَوَّلَ\nو مؤمن حرام می‌شمارد آنچه را که سالِ قبل حرام می‌شمرد.\nزمان که در حکم شرع تأثیری ندارد. غذایی که دیروز حلال بود، امروز حرام نمی‌شود و بالعکس. «حَرَامُ مُحَمَّدٍ إِلَی یوْمِ الْقِیامَةِ»؛ احکام تا قیامت تغییر نمی‌کند.\nهمه این حلال و حرام را می‌فهمند، بسیار امر ساده‌ای است، اما چرا حضرت آن را متذکر می‌شود؟! دلیلِ یادآوری چیست؟!\nبه‌خاطر بدعت…\n♦️وَأَنَّ مَا أَحْدَثَ النَّاسُ لَا یحِلُّ لَکمْ شَیئًا مِمَّا حُرِّمَ عَلَیکمْ\nبدعت‌هایی را که ایجاد کرده‌اند [أُحْدِثَ] آنچه را که بر مردم حرام گردیده، حلال نمی‌کند؛ بلکه خدا حلال یا حرام کرده است.\n((اصطلاح بدعت به هر کار جدیدِ بدیع می‌گویند و یکی از اسماءالله است که بدون نمونه قبلی خلایق را آفریده است.\nمنظور از بدعت هر چیزی است که غیر از دین باشد و در دین وارد کنند. طبق کلام حضرت، سنتی ترک شود و با حکم شرع مخالف باشد، بدعت است.))\n✳️گاهی بدعت چنان پیچیده می‌شود که اصل قطعی و مسلم دین، مانند حلال و حرامِ واضح، مغشوش می‌شود و مردم اشتباه می‌کنند و ازآن‌دست می‌کشند.\nملاکِ حرمت و ملاکِ حِلّیت، حکم خداست.\nحضرت در ابتدای حکومت این خطبه را ایراد فرمود: بدانید در حکومت اسلامی بدعت‌هایی ایجاد و حلال و حرام جابه‌جا شده، و من با آنها مبارزه می‌کنم. آگاه باشید، در مبارزه با بدعت‌ها معترض نباشید. باید اسلام را به مسیر اصلی خود برگردانیم.\nبدعت در این خطبه یک موضوع کلی است که مصداق آن بدعت‌های خلفا هستند. شما می‌دانستید که حکومت بعد از پیامبر حق من بود، بارها پیامبر تصریح کرده بود.\nولی یکباره بدعت ایجاد شد و دیگران آن را به دست گرفتند و شما با اینکه می‌دانستید حلال و حرام تغییر نمی‌کند، آنها غصب کردند و شما هم تأیید کردید.\nبدعت را خیلی دور مپندارید.\nسید عبدالحسین شرف‌الدین، صاحب کتاب‌های فراوان دیده می‌شود. سید عبدالحسین شرف‌الدین، صاحب کتاب المراجعات، حدود صد مورد مخالفت‌های قطعی خلفا با قرآن، سنت، احکام را ذکر می‌کند؛ لذا زمانی که حضرت از بدعت گلایه می‌کند، این‌طور نیست که در گوشه‌ای یک نفر کاری انجام داده باشد.\nصاحبان حکومت به طور گسترده در جامعه اسلامی بدعت‌ها را ترویج دادند.\n✳️نکته ۲: کسانی که بدعت گذاشتند، خود در همان بدعت چوب آن را خوردند.\nخلیفه دوم و سوم هر دو در بدعت خود کشته شدند. یکی از بدعت‌های خلیفه دوم این بود که بین عرب و عجم اختلاف انداخت، ایرانیِ تازه‌مسلمان را تحقیر می‌کرد و عرب‌ها را بالا می‌برد.\nکه عربِ مسلمان باارزش‌تر است از مسلمانِ عجم، درحالی‌که قرآن کرامت انسان را به تقوا می‌دانست. عرب و عجم، رنگ و نژاد ملاک نبود. کسی که خلیفه دوم را کشت داغ‌دیده‌ی این ماجرا بود. غلامِ مغیره بن شعبه (ابولولو) ایرانی بود. کینه خلیفه را به دل گرفت و کار او را تمام کرد.\nخلیفه سوم هم سنت پیامبر، تقسیم عادلانه بیت‌المال را از بین برد، مخصوص رؤسا و خانواده کرد، مردم شورش کرده و آتشی که برافروخته بود دامن‌گیر خود او شد. هم دنیا پای او را گرفت و هم در قیامت که آیات و روایات بسیار سنگین از عذاب برای بدعت‌گذار در نظر گرفته شده، او را خواهد گرفت.\n♦️وَلَکنَّ الْحَلَالَ مَا أَحَلَّ اللَّهُ، وَالْحَرَامَ مَا حَرَّمَ اللَّهُ\nحلال را خدا حلال کرده و حرام را خدا حرام کرده است.\nبسیار ساده است، ولی بسیار مهم… و امروزه در رسانه تبلیغات حجاب است.\nمخالف جمهوری اسلامی باحجاب مخالفت می‌کند. مگر حجاب محصول جمهوری اسلامی است! مگر جمهوری اسلامی ایجادکننده‌ی حلال و حرام بود!\nحکم الهی است و چگونه مسلمان می‌تواند با احکام الهی سازگار نباشد!\nبدعت‌هایی که امروزه ایجاد می‌شود و با همین فرمان فریب می‌دهند.\n♦️فَقَدْ جَرَّبْتُمُ الأُمُورَ وَضَرَّسْتُمُوهَا\nشما امور را بررسی کرده و تجربه کردید [جَرَّبْتُم] و محکم [ضَرْس] با عمق وجود دریافتید.\n♦️وَوُعِظْتُمْ بِمَنْ کانَ قَبْلَکمْ، وَضُرِبَتْ لَکمُ الأَمْثَالُ\nشما به اموری که قبل از شما بودند موعظه شدید، و مثال‌های فراوانی (در قرآن، روایات) برای شما زده شده است. بدعت چیزی نیست که آثار سوء و سوابق آن را ندیده باشید. بدعت باعث تفرقه و سستی دین می‌شود و شما دیده بودید.\nدو نمونه از خلفا که خون خود را پای این بدعت‌ها گذاشتند. شما از اهل بدعت طرف‌داری نکنید، باید با آنها مقابله کرد.\n✳️گاهی بدعت چنان ریشه‌دار شده، در عمق باور مردم می‌نشیند که مبارزه با آن شدنی نیست. مثال آن، با اینکه حضرت می‌فرماید با بدعت مقابله می‌کنم.\nدر کوفه، مرکز خلافت، در مسجدِ نزدیکِ دارالحکومه، نماز تراویه عمر نتوانست مخالفت کند\n(نماز مستحبی شب‌های ماه مبارک رمضان که در شرع باید فرادا خوانده شود، بدعت خلیفه دوم تبدیل به جماعت شد، اصل نماز سنت پیامبر بود؛ اما کیفیت آن را تغییر دادند.)\nآن‌قدر در عمق فرهنگ ریشه دوانده که گاهی حضرت با آن اقتدار نمی‌تواند مقابله کند.\nبحث آرمان‌ها یک حرف است که باید با بدعت مقابله کنیم، وقتی در عمل قرار گرفتیم بسیار سخت است، گاهی باید چند نسل بگذرد، ائمه‌ای شهید بشوند تا شیعه خودباور کند که نماز مستحبی را به جماعت نخوانند…\nمثال بدعت در قرآن:\n《وَقَالَتِ الْیهُودُ عُزَیرٌ ابْنُ اللَّهِ》 بدعت که ایجاد شد، انسان را فرزند خدایا در مسیحیت انسان را خدا می‌دانند.\n《وَقَالَتِ النَّصَارَی الْمَسِیحُ ابْنُ اللَّهِ》 از جهت اعتقادی مسیحیت متزلزل شد. برای بدعتِ یهود قرآن مثال می‌زند.\n《نَحْنُ أَبْنَاءُ اللَّهِ، لَنْ تَمَسَّنَا النَّارُ إِلَّا أَیامًا مَعْدُودَةً》 یهود ادعا می‌کرد ما هر چه کنیم مورد عذاب خدا قرار نمی‌گیریم، قرابت خویشی داریم؛ اگر ما را مؤاخذه کند چند صباحی ما را عذاب می‌کند.\n✅ چقدر از این تفکرات ما را منع کرده‌اند، هر کاری انجام می‌دهند و دلخوش کردند که امام حسین رحمت واسعه است.\nجایگاه هر شخص به شرطی بلند است که متمسک به اهل‌بیت باشد. شیعه اسمی نمی‌خواهند، شیعه‌ی عملی را دستگیری می‌کنند.\n♦️وَدُعِیتُمْ إِلَی الأَمْرِ الْوَاضِحِ\nشما به یک امر واضح و ملموس دعوت شدید و آن تبعیت از قرآن و سنت است که دچار فتنه و بدعت نشوید.\n♦️فَلَا یصِمُّ عَنْ ذَلِک إِلَّا أَصَمُّ، وَلَا یعْمَی عَنْهُ إِلَّا أَعْمَی\nدو گروه این سخن را نشنیده و نمی‌فهمند.\n۱- گروهی که از شنیدن کر شدند؛ چون قلب آنها کر شده [أَصَم]\n۲- گروهی که چشم قلب آنها کور شده است [أَعْمَی] چشم سر واضح می‌بیند؛ ولی چشم قلب با کوری تشخیص ندارد، حقایق فهمیده نمی‌شود.\n♦️وَمَنْ لَمْ ینْفَعْهُ اللَّهُ بِالْبَلَاءِ وَالتَّجَارُبِ لَمْ ینْتَفِعْ بِشَیءٍ مِنَ الْعِظَةِ\nکسی که با امتحان الهی سود نبرد، از تجربیات خود نفع نگرفت، از هیچ موعظه‌ای [عِظَه] سود نخواهد گرفت.\nتا وقتی از درون خود عبرت و پند نگیرد، حرف کسی در او تأثیرگذار نیست. تجربه و امتحان چنان ملموس هستند که انسان را بیدار می‌کند و کسی با آن بیدار نشد، چگونه از نصیحت دیگران بیدار شود و درس بگیرد!\nبرای یک‌لحظه ممکن است مؤثر باشد؛ ولی آنی از بین می‌رود. تأثیر اگر دائمی باشد، مانند چشمه باید از خودجوشش داشته باشد که هرگز خشک نمی‌شود. ریشه خشک‌شده را هر چه از بیرون شوک بدهند، تأثیر عمیق در حیات و زنده شدن ندارد.\n♦️وَأَتَاهُ النُّقْصُ مِنْ أَمَامِهِ\nکسی از تجارب استفاده نکند و از امتحان الهی متنبه نشود، مدام از پیش رو [أَمَامِهِ] نقصان به‌وجود می‌آید. روزبه‌روز به‌جای رشد، موانع بیشتر می‌شود… هر چه نفهمد سدّ راهِ خود را محکم‌تر کرده است.\n♦️حَتَّی یعْرِفَ مَا أَنْکرَ وَینْکرَ مَا عَرَفَ\nتا اینکه غایت کار او [حَتَّی] چنین می‌شود که خوب را بد و بد را خوب می‌پندارد. [یعْرِفُ]\nنظام فکری او عوض می‌شود.\n✅ اخلاق بحث فطری و درونی است؛ کلیات اخلاق نیاز به انبیا نداشت. اینکه عدالت خوب است، ظلم بد است، فطرت آن را می‌فهمد، درون می‌جوشد؛ اما وقتی درون گمراه، معطل و به مرداب تبدیل شد، همین اصول اصلی را هم نمی‌فهمد.\nدر خطبه یک فرمود:\nانبیا نیامدند چیزی بگویند که با طبع و فطرت شما مخالف باشد. انبیا آمدند تا فطرت انسان‌ها را شخم بزنند.\n《لِتُثِیرَ حَقَائِقَ الْقُلُوبِ》 فطرت هست ولی روی آن زنگارگرفته و صدایی نمی‌شنود. هبوط می‌کند به جایی که خوب و بد جابه‌جا می‌شود.\nدو عامل، سرآمد همهٔ موعظه‌ها هستند.\nالف. اگر بر کسی بلا آمد، باوجود بلا سر براه نشد، دیگر براه آمدنی نیست.\nب. اگر کسی تجربه کرد، دید نتیجهٔ هر عمل سوء بلایی بر او وارد می‌شود و باز هم موعظه نگرفت، گوش او کر و دل او مرده است.\nاگر بفهمید خدا به سبب بلا به شما نفع می‌رساند، بلا برای شما نعمت و رحمت است.\nعده زیادی از طریق بلا سر براه می‌شوند.\nچنین انسانی آن‌قدر در مسیر انحراف پیش می‌رود که خوب‌ها را بد می‌پندارد و بدها را خوب می‌بیند. سیستم او عوض می‌شود، چون موعظه نگرفت.\nدنیای زنده‌دلان با دنیای دل‌مرده متفاوت است. نتیجه درس نگرفتن از مواعظ است.\n♦️فَإِنَّ النَّاسَ رَجُلَانِ:\nدو صنف افراد در جامعه زندگی می‌کنند.\n♦️مُتَّبِعٌ شِرْعَةً\n۱- گروهی، تابعین شریعت هستند. خودرأی نبوده و حرف آنها بر اساس مرجع آنهاست.\n((شریعه رودخانه نیست، بلکه مسیر و راهی از رودخانه باز می‌کنند که راه دسترسی به رودخانه راحت‌تر باشد؛ چون اطراف رودخانه را نیزار پر می‌کند دسترسی به آب سخت می‌شود.)) دین و احکام الهی شریعت هستند که انسان را به رودخانه حقیقت (خدا) برسانند.\n♦️مُبْتَدِعٌ بِدْعَةً\n۲- گروهی، تابعین بدعت‌ها هستند.\nدر هر شرایطی برای خود نظر صادر می‌کنند.\n♦️لَیسَ مَعَهُ مِنَ اللَّهِ بُرْهَانُ سُنَّةٍ، وَلَا ضِیاءُ حُجَّةٍ\nاهل بدعت برای کار خود هیچ دلیل نقلی ندارند. هیچ دلیل روایی و قرآنی در دستشان نیست و دلیل عقلی هم ندارند. نه حجت شرعی دارند و نه حجت عقلی. جزو این گروه نباشید.\n♦️وَأَنَّ اللَّهَ سُبْحَانَهُ لَمْ یعِظْ أَحَدًا بِمِثْلِ هَذَا الْقُرْآنِ\nهیچ معلم و کتاب اخلاقی به‌اندازهٔ قرآن نمی‌تواند موعظه‌گر خوبی باشد.\n《قُلْ إِنَّمَا أَعِظُکمْ بِوَاحِدَةٍ أَنْ تَقُومُوا لِلَّهِ مَثْنَیٰ وَفُرَادَیٰ سَبَأَ - ۴۶》\nبه‌درستی که موعظه می‌کنم شما را که خالص برای خدا قیام کنید. دونفره دو نفر، یک نفر یک نفر. برای خدا عمل کنید.\n♦️فَإِنَّهُ حَبْلُ اللَّهِ الْمَتِینُ، وَسَبَبُهُ الْأَمِینُ\nموعظه قرآن چنان عمیق و باصداقت است که هرچه بگوید حقیقت است. رشته محکم خداست؛ به آن آویخته شوید، شما را نجات خواهد داد.\n♦️وَفِیهِ رَبِیعُ الْقَلْبِ\nهمان‌طور که فصل‌ها بهاری دارند، بهار نماد رویش است. قرآن هم بهار دل‌های شما است.\nاستعدادهای شما شکوفا می‌شود و به کمال می‌رسد.\n♦️وَینَابِیعُ الْعِلْمِ\nقرآن چشمه‌سار علم است.\nدر محضر قرآن به سرچشمه رسیدید. کوثری هست که پیوسته علم دارد.\n♦️وَمَا لِلْقَلْبِ جَلَاءٌ غَیرُهُ\nقرآن جلادهندهٔ دل‌های زنگارگرفته است.\n♦️مَعَ أَنَّهُ قَدْ ذَهَبَ الْمُتَذَکرُونَ\nکسانی که عامل به قرآن بودند، به قرآن متوجه، متذکر و مأنوس بودند، رفتند.\n♦️وَبَقِی النَّاسُونَ أَوِ الْمُتَنَاسُونَ\nباقی‌ماندگان یا قرآن را فراموش کردند [ناسون] یا خود را به فراموشی زدند.\nجامعه‌ای که از قرآن دور شد و افراد آن، از این دو گروه باشند «ناسون و متناسون»\nعلم و رویش در بین آنها معنا ندارد.\nکمال این است که به قرآن پیوند بخورید.\nاللهم زَینْ أَخْلَاقَنَا بِالْقُرْآنِ","بخش پنجم\nمتن:\nفَإِذَا رَأَيْتُمْ خَيْراً فَأَعِينُوا عَلَيْهِ، وَ إِذَا رَأَيْتُمْ شَرّاً فَاذْهَبُوا عَنْهُ، فَإِنَّ رَسُولَ اللَّهِ (صلی الله علیه وآله) كَانَ يَقُولُ: يَا ابْنَ آدَمَ اعْمَلِ الْخَيْرَ وَ دَعِ الشَّرَّ، فَإِذَا أَنْتَ جَوَادٌ قَاصِدٌ.\nانواع الظلم:\nأَلَا وَ إِنَّ الظُّلْمَ ثَلَاثَةٌ: فَظُلْمٌ لَا يُغْفَرُ وَ ظُلْمٌ لَا يُتْرَكُ و ظُلْمٌ مَغْفُورٌ لَا يُطْلَبُ؛ فَأَمَّا الظُّلْمُ الَّذِي لَا يُغْفَرُ فَالشِّرْكُ بِاللَّهِ، قَالَ اللَّهُ تَعَالَى: «إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ»، وَ أَمَّا الظُّلْمُ الَّذِي يُغْفَرُ فَظُلْمُ الْعَبْدِ نَفْسَهُ عِنْدَ بَعْضِ الْهَنَاتِ، وَ أَمَّا الظُّلْمُ الَّذِي لَا يُتْرَكُ، فَظُلْمُ الْعِبَادِ بَعْضِهِمْ بَعْضاً، الْقِصَاصُ هُنَاكَ شَدِيدٌ، لَيْسَ هُوَ جَرْحاً بِاْلمُدَى وَ لَا ضَرْباً بِالسِّيَاطِ وَ لَكِنَّهُ مَا يُسْتَصْغَرُ ذَلِكَ مَعَهُ. فَإِيَّاكُمْ وَ التَّلَوُّنَ فِي دِينِ اللَّهِ، فَإِنَّ جَمَاعَةً فِيمَا تَكْرَهُونَ مِنَ الْحَقِّ خَيْرٌ مِنْ فُرْقَةٍ فِيمَا تُحِبُّونَ مِنَ الْبَاطِلِ، وَ إِنَّ اللَّهَ سُبْحَانَهُ لَمْ يُعْطِ أَحَداً بِفُرْقَةٍ خَيْراً مِمَّنْ مَضَى وَ لَا مِمَّنْ بَقِيَ.\nلزومُ الطاعة:\nيَا أَيُّهَا النَّاسُ، طُوبَى لِمَنْ شَغَلَهُ عَيْبُهُ عَنْ عُيُوبِ النَّاسِ، وَ طُوبَى لِمَنْ لَزِمَ بَيْتَهُ وَ أَكَلَ قُوتَهُ وَ اشْتَغَلَ بِطَاعَةِ رَبِّهِ وَ بَكَى عَلَى خَطِيئَتِهِ، فَكَانَ مِنْ نَفْسِهِ فِي شُغُلٍ وَ النَّاسُ مِنْهُ فِي رَاحَةٍ.\nترجمه:\n(راه خدا و مسير قرآن، روشن است) هرگاه کار نيکى را مشاهده کرديد به آن کمک کنيد و هر زمان کار شرّى را ديديد از آن بگذريد; زيرا رسول خدا(صلى الله عليه وآله) مى فرمود: اى فرزند آدم، کار نيک انجام ده و بدى را رها کن که اگر چنين کنى در جاده مستقيم و ميانه (دور از افراط و تفريط) گام بر خواهى داشت.\nآگاه باشيد! ظلم بر سه گونه است: ظلمى که هرگز بخشوده نخواهد شد و ظلمى که بدون کيفر نخواهد بود و ظلمى که بخشوده مى شود و بازخواست ندارد; امّا ظلمى که بخشوده مى شود، ستمى است که بندگان با ارتکاب گناهان صغيره به خويشتن کرده اند و امّا گناهى که بدون کيفر نمى ماند، ظلم بندگان به يکديگر است که قصاص در آن جا شديد است. اين قصاص، مجروح ساختن با کارد يا زدن با تازيانه نيست ; بلکه چيزى است که اين ها در برابرش کوچک است.\nمبادا در دين خدا به رنگ هاى مختلف در آييد; چرا که اتحاد و اجتماع در راه حق ـ هر چند خوشايند شما نباشد ـ از پراکندگى در راه باطلى که مورد علاقه شماست بهتر است و خداوند سبحان به هيچ کس، نه از گذشتگان و نه باقى ماندگان به سبب اختلاف و تفرقه، نتيجه خوبى نبخشيده است.\nاى مردم! خوشا به حال آن کس که پرداختن به حال خويش او را از توجّه به عيوب مردم باز دارد و خوشا به حال آن کس که در خانه نشسته، روزى خود را مى خورد و به طاعت پروردگارش مى پردازد و بر گناه خويش مى گريد. چنين کسى به اصلاح خويش مشغول و مردم از دست او در آسايشند.\nتفسیر:\n خلاصهٔ قبل: حضرت گلایه می‌کنند که خوبان، اهل قرآن، عاملان به قرآن و کسانی که حرمت قرآن را نگه می‌داشتند، رفتند و آنان که ماندند، یا فراموش‌کارند یا خود را به فراموشی می‌زنند.\nفَإِذا رَأَیتُمْ خَیراً فَأَعِینُوا عَلَیهِ\nهر کجا خیری را دیدید، پس بر آن یاری کنید.\nوَإِذا رَأَیتُمْ شَرّاً فَاذْهَبُوا عَنْهُ\nو هر کجا شری را دیدید، آن را ترک کنید.\nحضرت، ملاک را خودِ خیر و خودِ شر معرفی می‌کنند. هر جا سفرهٔ خیر پهن است، شما هم کمک کنید و هر جا هر نوع شر، ظلم، بدعت و… بود، سریع از آنجا دور شوید. هیچ شرط و شروطی نمی‌گذارند. بدون تعصب خانوادگی و قومی، باید اهل انجام خیر بود و از شر دوری کرد و به‌خاطر دوست، فرزند و فامیل، از شر دفاع نکرد.\nفَإِنْ قالَ رَسُولُ اللهِ ص: یا ابْنَ آدَمَ، اِعْمَلِ الْخَیرَ، وَدَعِ الشَّرَّ، فَإِذا أَنْتَ جَوادٌ قاصِدٌ\nهمانا رسول خدا صلی‌الله علیه و آله فرمود: ای فرزند آدم، عمل خیر کنید و شر را رها کنید.\nاگر چنین باشید، پس تند و مستقیم به مقصد می‌رسید.\nجَواد، به معنای بخشنده است و معنای دیگر آن جاده است و معنای سوم آن، اسب تیزرویی است که سریع جاده را طی می‌کند. قاصد هم به معنای معتدل یا فردی است که از میانهٔ راه می‌رود تا به مقصد برسد.\nمنظور این است که شما در صورتی تند و مستقیم به مقصد نهایی می‌رسید که کار خیر انجام دهید و از شر گریزان باشید.\nولی اگر خیر را ترک کنید یا به شر کمک کنید، یا کند می‌روید یا به مقصد نمی‌رسید.\nچنان‌که در روایتی آمده است، کسی که از راه راست منحرف می‌شود، سرعت حرکت برای او سودی ندارد، مگر این‌که از مقصد دور می‌شود: لَا تَزیدُ سُرْعَةً إِلَّا بُعْداً.\nحضرت در ادامه، روی عنوان کلی شر، به نمونه‌ای از ظلم اشاره می‌کنند:\nأَلَا وَإِنَّ الظُّلْمَ ثَلاثَةٌ\nبدانید و آگاه باشید که ظلم سه گونه است.\nفَظُلْمٌ لا یغْفَرُ\nپس ظلمی که بخشیده نمی‌شود.\nوَظُلْمٌ لا یتْرَک\nو ظلمی که ترک نمی‌شود و بازخواست دارد.\nوَظُلْمٌ مَغْفُورٌ لا یطْلَبُ\nو ظلمی که بخشیده شده و طلب نمی‌شود.\nشناخت انواع ظلم بر همه لازم است.\nفَأَمَّا الظُّلْمُ الَّذِی لا یغْفَرُ فَالشِّرْک بِاللهِ قالَ اللهُ تَعالی: «إِنَّ اللهَ لا یغْفِرُ أَنْ یشْرَک بِهِ»\nو اما ظلمی که بخشیده نمی‌شود، شرک ورزیدن به خداست که در قرآن فرمود: به‌درستی که خداوند شرک ورزیدن به خود را نمی‌آمرزد.\nآیت‌الله خوئی ره در نهج‌البلاغه می‌نویسد که این آیهٔ ۴۸ سورهٔ نساء، آیهٔ مهمی در قرآن است و برخی محققان آن را رجای کامل می‌دانند و معتقدند امیدبخش‌ترین آیهٔ قرآن است.\nاما صاحب مجمع‌البیان یا نورالثقلین، پُرامیدترین آیه را این آیه می‌دانند:\n《قُلْ یا عِبَادِی الَّذِینَ أَسْرَفُوا عَلَیٰٓ أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَهِ اللَّهِ ۚ إِنَّ اللَّهَ یغْفِرُ الذُّنُوبَ جَمِیعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِیمُ زُمَر -۵۳》\nبگو: ای بندگان من که با ارتکاب گناه بر خود زیاده‌روی کردید، از رحمت خدا نومید نشوید؛ یقیناً خدا همهٔ گناهان را می‌آمرزد؛ زیرا او بسیار آمرزنده و مهربان است.\nحضرت امیر ذیل این آیه می‌فرماید که: مَا فِی الْقُرْآنِ آیةٌ أَوْسَعُ مِنْهَا؛ در قرآن، آیه‌ای به وسعت این آیه نیست.\nهر دو آیه نهایت رحمت خدا را می‌رسانند؛ اما دو نکته لازم به ذکر است:\nهر گناهی با توبه بخشیده می‌شود، حتی شرک. منظور این است که اگر کسی مشرک شد و تا آخر عمر توبه نکرد، خدا او را نمی‌بخشد؛ ولی اگر توبه کند، بخشیده می‌شود.\nطبق قاعدهٔ اولویت، وقتی خدا بزرگ‌ترین گناه را که شرک است می‌بخشد: إِنَّ الشِّرْک لَظُلْمٌ عَظِیمٌ، پس گناهان دیگر را هم می‌بخشد.\nقسمت دوم این‌که خدا گناهان کمتر از شرک را، اگر توبه هم نکرده باشد، می‌بخشد.\nآیت‌الله جوادی آملی می‌فرماید که همهٔ گناهان با توبه بخشیده می‌شوند و دیگر لِمَنْ یشاءُ ندارد. اما اوج رحمت خدا در آنجاست که می‌فرماید: 《لِمَنْ یشاءُ》؛ یعنی گناهکار توبه هم نکرده، شاید خدا ببخشد؛ مثلاً به‌خاطر این‌که در روضهٔ امام حسین شدیداً دل‌شکسته شود یا به‌خاطر بیماری یا انجام کار خیر دیگری، خدا او را ببخشد.\nچنان‌که امام صادق علیه‌السلام، وقتی با دوستانش به عیادت بیماری رفته بود و بیمار از شدت درد آه کشید، دیگران او را سرزنش کردند که چرا آه می‌کشی، نام خدا را ببر. امام فرمود: «آهْ مِنْ أَسْماءِ اللهِ».\nآیهٔ ۵۳ سورهٔ زمر ما را بین خوف‌ورجا قرار می‌دهد که شاید خدا ما را ببخشد یا شاید نبخشد. اما قطعاً و یقیناً این‌که عده‌ای گناهانی غیر از شرک داشته باشند و بدون توبه بمیرند، باز خدا آنان را می‌بخشد و این نهایت رحمت خداست.\nوَأَمَّا الظُّلْمُ الَّذِی یغْفَرُ فَظُلْمُ الْعَبْدِ نَفْسَهُ عِنْدَ بَعْضِ الْهَناتِ\nو اما ظلمی که بخشیده می‌شود، ظلم به خود است در کارهای کوچک و گناهان صغیره، هنات.\nظلم انسان به نفس، انجام گناه صغیره‌ای است که جای بخشش دارد.\nمانند گذراندن جوانی به بطالت و عیاشی که در اثر گذشت زمان، آسیب‌های آن دامن‌گیر می‌شود و موجب تحقیر، سرشکستگی و محرومیت‌های مادی او می‌گردد.\nدر قرآن کریم، ترک گناهان کبیره خود موجب محو سیئات معرفی شده است؛ به‌پاس حرمتی که رعایت کرده است. اما گناهان صغیره گاهی در اثر تکرار، اصرار و کوچک‌شمردن، به گناه کبیره تبدیل می‌شوند.\nوَأَمَّا الظُّلْمُ الَّذِی لا یتْرَک فَظُلْمُ الْعِبادِ بَعْضُهُمْ بَعْضاً\nو اما ظلمی که ترک نمی‌شود، ظلم بندگان به یکدیگر است. خداوند دربارهٔ ظلم به دیگران و حق‌الناس مصالحه و گذشت نمی‌کند و محاسبه و مؤاخذه خواهد کرد.\nمتأسفانه، در دوران حاضر، انسان‌ها به‌شدت گرفتار ظلم به هم و حق‌الناس هستند. با قضاوت‌های بی‌جا و به‌ناحق، بدون تحقیق و بررسی، دربارهٔ دیگری حرف‌زدن و اظهارنظرکردن و… انسان‌ها درگیر حق‌الناس هستند که خدا آن را سخت پیگیری، محاسبه و در نهایت مجازات خواهد کرد.\nدر روایتی از امام صادق علیه‌السلام است که فرمود: خداوند به یکی از انبیا وحی کرد که سراغ حاکم زمانه‌اش برود و بگوید که اگر منِ خدا به تو قدرت دادم، برای آن است که به مردم ریاست کنی و حق مظلوم را از ظالم بگیری، نه آنکه به آنان ظلم کنی؛ و من از ظلمی که به آنان شده است، دست برنمی‌دارم، حتی اگر کافر باشند.\nخداوند روی حق‌الناس بسیار غیرتمند است و حتی ظلم به کافر را هم نمی‌بخشد.\nکسی که با گناه و حرف نابجای خود به‌نظام اسلامی و خون سیصد هزار شهید ظلم می‌کند و به آبروی حکومت اسلامی لطمه می‌زند، مسلماً مؤاخذه و عذاب خواهد شد.\nالْقِصاصُ هُناک شَدیدٌ\nقصاص آنجا شدید است.\nمی‌فرماید در مورد حق‌الناس، عقوبت آن، قصاص، در آخرت شدیدتر است.\nقصاص به معنای قصاص دنیایی نیست، بلکه شدت عقوبت است.\nلَیسَ هُوَ جُرْحاً بِالْمُدی وَلا ضَرْباً بِالسِّیاطِ\nو عقوبت آن جراحت با چاقو، مُدی، و ضربات شلاق نیست. عقوبت خدا در قیامت مثل دنیا نیست که مجرم را با چاقو خراش بزنند و قطعه‌قطعه کنند یا شلاق بزنند.\nوَلٰکنَّهُ ما یسْتَصْغَرُ ذلِک مَعَهُ\nبلکه این مجازات، در مقابل عقوبت آنجا ناچیز و کوچک است.\nیعنی سخت‌ترین عذاب‌های دنیا در برابر عذاب‌های اخروی چیزی نیستند، چه برسد به عذاب‌های شدید. تحمل سختی در جبران‌کردن حق‌الناس، هرچند سخت باشد، در مقابل عذاب‌های اخروی هیچ است.\nفَإِیاکمْ وَالتَّلَوُّنَ فی دِینِ اللهِ\nاز رنگ‌پذیری در دین خدا پرهیز کنید.\nمبادا در دین خدا هر روز به رنگی، چهره‌ای و حزبی درآیید. بپرهیزید از این‌که هر روز، طبق عرف عامهٔ مردم، رنگ دین‌داری شما هم عوض شود. یکی از عوامل رنگ‌پذیری، با هم بودن و در اجتماع حاضرشدن است؛ لذا حضرت در ادامه می‌فرماید:\nفَإِنَّ جَماعَةً فیما تَکرَهُونَ مِنَ الْحَقِّ خَیرٌ مِنْ فُرْقَةٍ فیما تُحِبُّونَ مِنَ الْباطِلِ\nاجتماعی که بر حق باشد، هرچند از آن کراهت داشته باشید، بهتر است از تفرقه در راه باطلی که گرچه آن را دوست می‌دارید.\nشاید از حق ناراحت شوید، ولی همیشه طرف‌دار حق باشید و از باطل دوری کنید، هرچند که مورد پسند شما باشد؛ و خیر شما در اتحاد است. تفرقه همیشه باطل و اتحاد همیشه حق است.\nوَإِنَّ اللهَ لَمْ یعْطِ أَحَداً بِفُرْقَةٍ خَیراً مِمَّنْ مَضی وَلَا مِمَّنْ بَقِی\nهمانا خداوند به احدی به‌خاطر تفرقه خیروبرکت عطا نکرده است؛ چه آنان که بوده‌اند، مضی، و چه آنان که بعداً می‌آیند، بقی.\nهر کس دم از تفرقه و انشقاق بزند، خدا به او خیری نمی‌دهد. همه باید دور محور حق‌وحقوق جمع شوند، هرچند خوششان نیاید.\nسنت خدا این است که اجتماع در راه حق برکت می‌آورد، ولی با آمدن تفرقه، برکت می‌رود.\nلازم به توضیح است که اختلاف و فرقه تفاوت دارند. اختیار، لازمهٔ انسان و جامعهٔ بشریت است. هر انسانی بنا به تفاوت‌های فردی، محیط تربیتی، رفتار و افکار خاص خود را دارد. ما با اختلاف مشکلی نداریم. اختلاف بین زن و شوهر، پدر و فرزند، دو دوست و همکار، نه‌تنها بد نیست، بلکه خوب هم هست؛ ولی تفرقه لازمهٔ زندگی نیست و زندگی را از بین می‌برد؛ باید از آن پرهیز کرد.\nباوجود اختلافات، باید وحدت داشته باشیم. به‌خصوص شیعه و سنی آن‌قدر مشترکات زیاد دارند که می‌توانند حول یک محور جمع شوند. در روایت نبوی آمده است: «اِخْتِلافُ أُمَّتِی رَحْمَةٌ» که دربارهٔ آن تفاسیر فراوانی آمده است. یک تفسیر آن این است که اختلافی که منجر به تفرقه نشود، بلکه موجب تضارب آرا شود، خیلی هم خوب است؛ زیرا با بیان ادله‌ها، تحقیق و بررسی‌ها در حین گفت‌وگو، موجبات پویایی و رشد افراد فراهم می‌شود و در تضارب آرا حق معلوم می‌شود. چنان‌که ائمه علیه‌السلام اهل مناظره بودند؛ در این گفت‌وگو، مناظره و کلنجاررفتن‌ها با افراد مخالف، حق معلوم و آشکار می‌شد. پس اختلاف باعث برکت می‌شود.\nتفسیر دوم را مرحوم شیخ صدوق ره در معانی الاخبار، ذیل روایتی از امام صادق علیه‌السلام بیان می‌کند که یکی از معانی اختلاف، تضارب آراست؛ ولی عرب به رفت‌وآمد هم اختلاف می‌گوید، مانند گردش شب‌وروز که در قرآن کریم از آن به اختلاف تعبیر شده است:\n《إِنَّ فِی خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّیلِ وَالنَّهارِ لَآیاتٍ لِأُولِی الْأَلْبابِ آلِ عِمْرانَ - ۹۰》\nیقیناً در آفرینش آسمان‌ها و زمین و آمدورفت شب‌وروز، نشانه‌هایی بر توحید، ربوبیت و قدرت خدا برای خردمندان است.\nاختلاف یعنی از هر قبیله و شهری به مراکز علمی آمده و علوم دینی را فرابگیرند و بعد در شهرهای خود مبلغ دین باشند. رفت‌وآمد مبلغان دین رحمت است. دین را می‌گیرند و به مردم می‌رسانند. این اختلاف باعث رحمت است، به‌شرط این‌که به تفرقه نرسد.\nیا أَیهَا النّاسُ طُوبی لِمَنْ شَغَلَهُ عَیبُهُ عَنْ عُیوبِ النّاسِ\nای مردم، خوشا به حال کسی که مشغولیت به عیوب خود، او را از عیوب مردم باز بدارد.\nتمام عمر به عیب‌های خود مشغول است و دیگر فرصتی برای پرداختن به عیوب مردم باقی نمی‌ماند.\nوَطُوبی لِمَنْ لَزِمَ بَیتَهُ وَاشْتَغَلَ بِطاعَةِ رَبِّهِ\nو خوشا به حال کسی که در خانهٔ خود نشسته، لَزِمَ فِی بَیتِهِ، و به طاعت پروردگار خود مشغول است.\nیعنی با جباران نشست‌وبرخاست ندارد و به داشته‌های خود راضی است و مشغول اطاعت خداوند است. شغل او بندگی است؛ در هر کاری که باشد، خانه‌دار باشد یا معلم، پزشک باشد یا کارمند، در همه حال مشغول بندگی خداست و نیز عبادت‌های دینی خود را هم انجام می‌دهد.\nوَبَکی عَلی خَطیئَتِهِ\nو بر خطا و گناه خود گریه می‌کند.\nخوشا به حال کسی که به‌خاطر معاصی خود اهل گریه و بکاء است.\nفَکانَ مِنْ نَفْسِهِ فی شُغْلٍ وَالنّاسُ مِنْهُ فی راحَةٍ\nخوشا به حال کسی که به خود مشغول است و مردم از دست او در امنیت و آسایش هستند.\nبه کسی ضرر و آسیب نمی‌زند و حق‌الناسی به گردن ندارد.\nدر خصوص عبارت اجتماعی بودن و انزواگزینی، لازم به ذکر است که اسلام هم به اجتماع دعوت می‌کند و هم گاهی به گوشه‌گیری و انزوا در برخی موارد توصیه می‌کند.\nبه‌عنوان نمونه، عثمان بن مظعون بعد از مرگ فرزند خود گوشه‌گیر شده و در مسجد معتکف شده بود. پیامبر اکرم صلوات‌الله‌علیه و آله به او فرمود: «إِنَّ اللهَ لَمْ یکتُبْ عَلَینَا الرَّهْبانِیةَ إِنَّما رَهْبانِیةُ أُمَّتِی الْجِهادُ فی سَبیلِ اللهِ».\nخداوند بر ما رهبانیت ننوشته، بلکه رهبانیت امت من در میان میدان جهاد است.\nعثمان بن مظعون در میان اصحاب پیامبر جایگاه ویژه‌ای داشته، به‌گونه‌ای که امیرمؤمنان علی علیه‌السلام به‌خاطر علاقه به او، نام فرزندی از خود را عثمان نهاده بود.\nدر خطبهٔ ۱۶ فرمود: «فَاسْتَتِرُوا فِی بُیوتِکمْ»؛ در خانه‌هایتان پنهان شوید. باتوجه‌به آیات و روایات می‌بینیم که در اسلام به گوشه‌گیری و انزوا هم توصیه شده است.\nدر خطبهٔ ۱۲۷ فرمود اگر کسی از مردم جدا شود، نصیب شیطان می‌شود؛ همان‌طور که گوسفندی که از گله جدا شود، نصیب گرگ می‌شود. در جمع این دو توصیه، یعنی توصیه به اجتماع و توصیه به انزوا، باید گفت اگر حکومت مؤمنانه، دورهٔ صلاح و مردم دین‌دار باشند، وظیفهٔ ما حضور در اجتماع و اجتماعی بودن است؛ باید در میان خلق بود. اما وقتی اوضاع خوب نباشد و حکومت فاسد، با مردم بودن باعث آسیب به دین‌داری شود، آنجا توصیه به گوشه‌نشینی شده است.\nالْحَمْدُ لِلَّهِ رَبِّ الْعالَمینَ"]});
